import { createContext, useContext, useState, useCallback, ReactNode, useEffect } from 'react'
import { setApiLocale } from './api'

export type Locale = 'zh' | 'en'

/** 数字/日期格式化用的 BCP-47 标签。
 *  裸调 toLocaleString() 会跟随浏览器/机器区域设置（例如 de-DE 把 1234
 *  渲染成 "1.234"），必须显式传入当前 UI 语言。 */
export const numLocale = (l: Locale): string => (l === 'zh' ? 'zh-CN' : 'en-US')

