    'vmaxq.diag.sources': '数据源命中',
    'vmaxq.diag.explain.availability': '业务可用性：按 1100（业务面流程记录）的 procedure_status 分布打分 —— Success 加分，Timeout / Failure 扣分，并对 `S1-U Path Failure` **单独硬扣分**：它在 status 里常常仍记 Success（Failure 表示"送达失败"而不是"业务失败"），只按 status 算会把用户面断流算成正常。',
    'vmaxq.diag.explain.latency': '响应时延：主判据 = 1300 的 `$first_resp_delay` **P90**（权重 0.7），副判据 = `$tcp_resp_delay` 均值（0.3）。用 P90 而不是均值，是因为实测同一窗口均值 455ms、峰值 118,765ms —— 均值被大量小包拉平，而用户抱怨的正是卡住的那几个请求。',
    'vmaxq.diag.explain.transport': '传输质量：重传率 =（上行 + 下行重传包）÷（上行 + 下行总包）× 100，失序率同式，两个率一起打分。**总包数为 0 时不算比率**，只看绝对数 —— 上游部分记录的单位是 KB 而字段名没变，硬除会算出假的率。',
    'vmaxq.diag.explain.radio': '无线覆盖：取 32 号源（无线侧采样）的 RSRP **P10**（不是均值）配 SINR / CQI 打分。用 P10 是因为弱覆盖由"最差的那几分钟"决定，均值 -95dBm 的用户照样可能在某个小区掉到 -120 打不通电话。',
    'vmaxq.diag.explain.common': '这四张分数是**前端按规则文件算的**（`pages/vmaxDiagnosisRules.ts`），接口不下发分数；输入就是下面「数据源命中」列出的行集。满分 100，显示 — 表示该维度所需的源一行都没取到。',
    'vmaxq.diag.explain.sources': '这一行是各数据源**本次实际取回的行数**（前端取接口 rows 数组长度）。后端按 HTTP 分页取数，各源上限为 1300 = 1200 行、1100 = 800 行、32 = 600 行、1301 = 200 行；标签末尾的 * 表示接口返回 truncated=true，即**还有行没取回** —— 此时上面四维分数只是样本口径。当前合计取回 {n} 行。',
    'vmaxq.diag.explain.srcRows': '{src}：本次取回 {n} 行（接口 rows 长度）。后端对该源设了分页上限，标签末尾带 * 说明接口报了 truncated=true，**还有未取回的行**，因此基于该源的统计都只是样本而非全量。',
