    'vmaxq.voice.mode.none': '未识别到语音活动',
    'vmaxq.voice.sgs': 'SGs 位置更新',
    'vmaxq.explain.voiceCard': '整卡数字由前端 analyzeVoice 在 **1100（业务面流程）+ 1300（话单）** 两个源的行集上算出，接口不下发这些计数。模式判定：1300 里有 QCI=1 → VoLTE；否则 SGS / ESR / CSFB 任一有记录 → CSFB；都没有 → 无语音活动。',
    'vmaxq.explain.vSgs': '1100 里 interface 为 SGS 的**行数**（SGs 接口位置更新）—— CSFB 判据链的第一环。',
    'vmaxq.explain.vTrig': '1100 里 request_cause 含 CS FALLBACK TRIGGERED 的行数，即网络确实下发了回落触发。',
    'vmaxq.explain.vEsr': '1100 里 procedure_type 含 EXTENDED SERVICE REQUEST 的行数（终端发起的 ESR）。下面那个成功率就是按这批算的。',
    'vmaxq.explain.vPage': '1100 里 procedure_type 含 PAGING 的行数（被叫寻呼）。',
    'vmaxq.explain.vBad': '1100 里 procedure_status 为 TIMEOUT 或 FAILURE 的**行数**，逐行计一次。⚠ 2026-11-05 前有一条重复计数：PAGING 的超时/失败行既进 PAGING 分支又进通用分支，会被加两遍，现已修正 —— 同一时点的旧截图里这个数会偏大。',
    'vmaxq.explain.vQci1': '1300（话单）里 qci 等于 1 的行数，即 VoLTE 语音承载。刻意不按 qci=0 统计 —— 实测 qci=0 的那批是 DNS 小包。',
    'vmaxq.explain.vRate': '= ESR 成功数 ÷ ESR 总数 × 100（都在 1100 上算，非 TIMEOUT/FAILURE 记为成功），保留 1 位小数。没有 ESR 时显示 —，不是 0%。',
    'vmaxq.explain.vFallback': 'CSFB 回落耗时 = 每次 ESR 之后**第一条** UE CONTEXT RELEASE 的时间差，只取 >0 且 <30 秒的样本再求平均，四舍五入到整数毫秒。没有有效配对时显示 —。',
    'vmaxq.explain.ottCard': '整卡由前端 analyzeOtt 在 1300 源的行集上算出：先按 subservice / app_content_name / protocol 判定哪些行算 OTT 通话，再按 App 聚成会话。接口不下发这些值。',
    'vmaxq.explain.ottSessions': '= 前端聚出的 **OTT 会话条数**（sessions 数组长度），不是命中的话单行数。',
    'vmaxq.explain.ottDuration': '= 各会话时长之和（秒），带单位的文本由 durText 渲染（中英文单位不同）。',
    'vmaxq.explain.ottRtt': '= 通话会话 dl_avg_rtt 的算术平均，四舍五入到整数 ms。>150 会染红 —— 那只是规则文件里的显示阈值，不是业务达标线。',
    'vmaxq.explain.ottJitter': '= 同一批通话 RTT 的**标准差**（stdDev），不是最大值减最小值。>60 染红同样只是显示阈值。',
    'vmaxq.explain.ottRetrans': '=（上行 + 下行重传包）÷（上行 + 下行总包）× 100，保留 2 位小数；总包为 0 时记 0 而不是除零。**分母是本次取回这批行的合计**。',
    'vmaxq.explain.ottBaseline': 'baseline = **非通话**流量记录的 dl_avg_rtt 均值（对照组），四舍五入到整数 ms：用来判断「RTT 高是 OTT 本身还是整条链路都慢」。当前 {v} ms。',
    'vmaxq.explain.gameFound': '⚠ 这个 N 在代码里叫 sessions，实际 = 各命中 App 的**话单行数之和**（Σ records），不是会话条数。命中判据分三档：subservice 为 GAME/GAMING、App 名含游戏关键词、或名字含 game/play 且不是 NETWORK STORAGE（第三档在表里标「疑似」）。',
    'vmaxq.explain.gameRecords': '该 App 命中的 1300 行数（records）。列标题写的是「流量」，但这一格给的是**行数**。',
    'vmaxq.explain.gameRtt': '= 该 App 各话单 dl_avg_rtt（该值缺失时取 ul_avg_rtt）的算术平均，四舍五入整数 ms；没有 >0 的 RTT 时显示 —。',
    'vmaxq.explain.gameJitter': '= 该 App 同一批 RTT 的标准差（整数 ms）。只有 1 条 RTT 时算不出离散，显示 —。',
    'vmaxq.explain.gameRetrans': '=（上行 + 下行重传包）÷（上行 + 下行总包）× 100，保留 2 位小数；总包为 0 时显示 —。',
    'vmaxq.explain.rSamples': '= max(RSRP 有效样本数, SINR 有效样本数)：读数为 0 的行不进样本。下方小字是各制式（2G/3G/4G/5G）各自的分摊行数。',
    'vmaxq.explain.rRsrpAvg': '= 全部有效 RSRP 读数的算术平均，四舍五入整数 dBm。颜色分档 -110 / -100 只是显示阈值。',
    'vmaxq.explain.rRsrpP10': '= RSRP 的 **P10 分位**（最差 10% 的分界），不是均值。弱覆盖由最差的那几分钟决定：均值 -95dBm 的卡照样可能掉到 -120 打不通电话。',
    'vmaxq.explain.rSinrAvg': '= SINR 有效读数的算术平均，保留 1 位小数，单位 dB。显示 0 表示没有有效读数。',
    'vmaxq.explain.rCqiAvg': '= CQI 有效读数的算术平均，保留 1 位小数。**没有 CQI 读数时显示 —**，不显示 0。',
    'vmaxq.explain.ccaCells': '= 接口 CCA 查询返回的驻留小区数组长度（前端取 .length）。下方表格每页 10 行分页展示，各页加起来等于这个数。',
    'vmaxq.explain.ccaCauses': '= 接口 result.causes 数组长度：一条 = 一项弱质指标（KQI 代码 + 对象 + 时间），**不是去重后的原因种类数**。',
    'vmaxq.explain.flowTotal': '= 接口 total_flux：本次从 XDR **取回的那批记录**的流量合计（后端按 KB 格式化）。上游取数有条数上限，所以它是这批的合计，不等于该用户窗口内的全量流量。',
    'vmaxq.explain.flowCatTraffic': '= 接口该分类的流量合计（分类内各 App 之和），单位由后端 _fmt_bytes_kb 决定。',
    'vmaxq.explain.flowRatio': '= 接口下发的占比字符串：该 App 流量 ÷ **所属分类**合计 × 100，保留 1 位小数；分类合计为 0 时后端直接给 —。注意分母是分类，不是全部流量。',
