    'eflowFlow.explain.steps': '数的是该单**实际走过的流程节点数**（去重后按规范顺序排列），不是操作次数。\n告警发生与 TT 建单**无条件打点** —— 只要查到单，起点就是 2 步。\n只统计 TT 主流程，WO 现场子流程另有一条泳道，不计进这个数。\n全程分母 {{n}} = 主流程节点数（不含 WO 泳道）。',
    'eflowFlow.tip.steps': '本单走过 **{{reached}}** 个主流程节点 / 全程 {{total}} 个\n告警发生、TT 建单为无条件打点\nWO 子流程另计：走过 {{wo}} 个节点（不进上面的数）\n点卡片清除节点选中',
    'eflowFlow.explain.rulesTotal': '分母 = ocrule_details **整表行数**：后端查询不带任何 WHERE / 时间过滤，取的是当前规则库快照。\n不是「本单走过的规则数」，也不是「生效规则数」。\n其中挂在流程节点上的有 {{nodes}} 个节点（共 {{total}} 个节点）。',
    'eflowFlow.tip.rules': '规则表共 **{{rules}}** 条（全库，未过滤）\n界面里的「本单命中 {{hits}} 条」= **当前所在节点**挂载的规则 + 建单定级规则去重后的条数\n命中数不是全过程累计 —— 单子在流转，这个数字跟着当前步骤变',
    'eflowFlow.explain.nodeRulesTooltip': '挂载数：该节点声明的触发步骤命中的规则，按（规则名, 类型, 触发步骤）去重；生效数：status 严格等于 ACTIVE（区分大小写）。',
    'eflowFlow.tip.nodeActive': '该节点 **{{active}}** 条规则的 status 严格等于 ACTIVE\n挂载 {{total}} 条中剩下的不是「失效」就是大小写不匹配（Active / active 不计）',
    'eflowFlow.tip.nodeTotal': '挂载到该节点 **{{total}}** 条规则\n去重键 =（规则名, 规则类型, 触发步骤）\n同一条规则可挂在多个节点上，各节点分别计数 —— 把各节点相加会超过全库 {{rules}} 条',
    'eflowFlow.explain.graph': '底图 = 规则驱动的状态机：节点是 eFlow 的步骤，连线由规则的**触发步骤**与**推送路径**推导。\n高亮 = 该单实际走过的节点与相邻连线。\n节点上「生效/总数」= 挂到该节点的规则数，悬浮节点可看构成。',
