    'eflowFlow.calcNote.graph2': '连线由规则的 triggerStep 与「推送路径」推导：步骤名先经 _step_to_node 归一（剥掉 GroupConfig_ / GroupDefault_ / CustomTitle_ 前缀），映射不到规范节点的规则不会产生连线。',
