    'qa.explain.umeHistoryTotal': '「命中 N」的 N = 接口 history.total，即 UME 返回的 totalcount（同一查询条件下 UME 侧的总条数）。本项按**同站点 + 该告警发生时刻 ±2 分钟**取历史，单次最多回传 30 条，所以 UME 报的总数常常大于表格行数。取不到时显示 —，不冒充 0。',
    'qa.explain.umeHistoryShown': '括号里的 {n} = 本次实际取回并渲染的行数（接口 history.count），上限 30 条。差额不是丢了，是 UME 单次只回传前 30 条。',
    'qa.explain.ruleCount': 'N = 后端读 eflow_TT_rules.xlsx 得到的 ACTIVE 规则条数（接口 rules.count）。旁边两个时间是该表的更新时间与本次采集时间 —— 判定结果与手册对不上时，先看这两个时间是否过期。',
    'qa.explain.pushRuleHit': 'N = 命中本单推送规则的条数（前端对接口回传的命中数组取长度，不做二次筛选）。一条都没命中时显示「无命中」而不是 0。',
    'qa.explain.cells': '括号里的 {n} = 接口回传的同站小区总数（前端取数组长度）。下方标签**最多只画 60 个**，多出来的小区不在画面上。',
    'qa.explain.docCount': '{n} = 文档目录树扫描到的条目数（前端取接口返回数组的长度），后面的路径是当前扫描的根目录。',
    'qa.explain.sectionCount': '括号里的 {n} = 「{sec}」这一节的字段条数（接口 report.fields[].items 的长度）。点标题展开可逐条核对。',
    'qa.explain.searchHits': '{n} = 本次全文检索命中的**文档数**（前端取命中数组长度），不是关键词出现次数，也不是行数。',
    'qa.explain.elapsed': '{v} 秒 = 接口 elapsed_total_sec（没有该字段时回落 elapsed_sec），覆盖「读库 + 规则匹配 + 组装响应」整段后端计时，**不含**前端渲染与网络往返。',
    'qa.explain.bInput': '有效单号 {valid} = 接口 input.valid：把粘贴文本拆分、去空、去重后，剩下能参与判定的单号数。接口另外几个数没显示在这里 —— 原始 {total} 个、非法 {invalid} 个、重复 {dup} 个（取 input.invalid / input.duplicated 数组长度）。若 input.truncated 为真，说明输入超过接口上限，多出来的没参与判定。',
    'qa.explain.bFound': '= 接口 summary.found：在 eflow_tt 表里查到记录的单号数。',
    'qa.explain.bMiss': '= summary.not_found：查不到记录的单号数。明细在「未找到」清单里，不在下面的表格里。',
