    'cr.explain.cards': '八个桶的判据都在后端算（表 eflow_cr，时间列 request_registration_time）：\n已排期 = planned_start_time 非空；已执行 = actual_start_time 非空；按时完成 = 已执行 **且** actual_start_time ≤ planned_start_time；未执行 = 已排期但 actual 为空；已关闭 / 已取消 / 在办 = status 归一后等值或 NOT IN。\n⚠ 「按时」是**文本字典序**比较，依赖上游时间格式一致（代码注释自己承认这是假设）。',
    'cr.tip.sumOverCats': '本数 = 接口 summary：后端在**同一条 SQL** 里按已选的 {{n}} 个类别收窄后算好（类别筛选走参数化 IN，不拼字符串）。\n页面不再自己把分类计数相加 —— 概览、三个比率、类别表、状态分布、月度与子类别都出自同一个集合；不勾类别即全量。',
