    'pm.explain.overdue': '超期 = `UPPER(TRIM(pmt_overdue)) = \'YES\'` —— **直接采用源表自己的判定，页面不按计划/实际日期自行推算**（这一点很关键：源表没填该列时这里恒为 0，不代表真的没超期）。',
    'pm.explain.onTime': '未超期 = pmt_overdue 归一后不等于 YES。它与「超期」互补，覆盖同一分母（总单量）。',
    'pm.explain.notStarted': '未开始 = 该工单的**条目完成数 = 0**（completed_items 由明细行里已完成的条数累加得到）。',
    'pm.explain.closedOverdue': '已关闭但超期 = 同时满足 status=CLOSED 与 pmt_overdue=YES。',
    'pm.explain.openOverdue': '未关闭且超期 = 同时满足 status≠CLOSED 与 pmt_overdue=YES —— 这张卡才是「现在最该追」的一批。',
    'pm.explain.rateClosure': '关闭率 = 已关闭 ÷ 总量。',
    'pm.explain.rateOverdue': '超期率 = 超期 ÷ 总量。**越低越好**，所以染色用反向着色（高=红）。',
    'pm.explain.rateStart': '开工率 = (总量 − 未开始) ÷ 总量，即「至少完成了一条」的工单占比。',
    'pm.tip.count': '本数 = 接口 summary 的该字段 = **{v}**（后端一条 SQL 里 SUM(CASE WHEN …) 数出来的）\n占总量 {total} 的多少由你自己心算 —— 页面不下发占比字段\n点卡片下钻，明细行数与这个数严格相等',
    'pm.tip.countTotal': '本数 = 接口 summary 的 total = **{v}**：时间窗口内该数据源的工单行数，后端一条 COUNT 数出来的\n它同时是下方关闭率与超期率的分母\n点卡片下钻**全部**工单明细，行数与这个数严格相等',
    'pm.tip.rate': '{rate}\n分母见下方小字；比率由后端 `_rate` 算（分母为 0 时返回 null → 显示 —，不是 0%）',

