    'noc.explainCard.nocCount': '进入排名的人数 = 本月有单落在 **last_processer** 上的处理人分组数。\n同一张单只记在**最后处理人**名下，换手不换人合计。\n搜索框是 LIKE 包含匹配，会把这里的人数连同下面所有统计一起缩小。',
