    'noc.explainCard.total': '各人单量之和。一行 TT 记一次，归属字段是 **last_processer**（不是当前处理人 current_handler）。\n时间归属用 alarm_occur_time 落月，与告警看板同字段。',
    'noc.tip.total': '合计 **{{v}}** 单，分摊在 {{people}} 人名下\n人均单量随搜索与承接方筛选变化',
    'noc.explainCard.avgMismatch': '⚠ 这是**各人错位率的算术平均（每人一票）**，不是 Σ错位 ÷ Σ单。\n人的错位率 = 错位单 ÷ **填了根因的单**（分母不是全部单），没填根因的人不进平均。\n代码本意豁免 Auto-recovery / Uknown / Force Majeure / Planned work，但豁免元组是混合大小写而填报值被 upper()，**实际从未命中** —— 这几类单目前仍算错位（属实现缺陷，已登记待业务确认，未擅自改）。',
    'noc.tip.avgMismatch': '各人错位率的等权平均 = **{{v}}%**\n判红阈值 ≥30%（红旗同一条）',
    'noc.explainCard.avgDur': '各人平均处理时长的**算术平均（每人一票）**，单位小时。\n单条时长由 create / fo_accept / fo_process / confirm 等明细文本正则解析，**>7 天按误报剔除**，缺明细的单不进平均。',
    'noc.tip.avgDur': '各人时长的等权平均 = **{{v}} 小时**\n判红阈值 ≥12h（红旗同一条）',
    'noc.explainCard.slaPass': '与上面两张不同：这是**合并口径** ΣPass ÷ Σ(Pass+Failed)，按单量加权，不是各人通过率的平均。\n所以它可能明显高于或低于「各人平均」—— 单量大的人说话更响。\n分母只收 sla_status 为 Pass / Failed 的单，其他状态与空值不进分母。',
    'noc.tip.slaPass': '合并口径通过率 = **{{v}}%**\n判绿阈值 ≥90%，低于则标橙\n分母只含 Pass / Failed 两类，未算 SLA 的单不在里面',
    'noc.explainCard.redFlag': '红旗**人数**：命中任一条件即算一个人（多因不重复计）。\n三条阈值：错位率 ≥30%、平均处理 ≥12 小时、SLA Fail 率 ≥50%。\n具体命中哪几条在下方红旗条里展开看；原因文字由后端拼，当前只有中文。',
    'noc.tip.redFlag': '本月红旗 **{{n}}** 人\n判据：错位率 ≥30% 或 平均处理 ≥12h 或 SLA Fail ≥50%\n一人多因只计一次',
