    // ---- 数字悬浮说明（2026-11-05，AGENTS.md 三.3c）：口径从 services/fme_data/fme_ranking_service.py 核实 ----
    'fme.tip.fmeCount': '本月进入榜单的 FME 数（接口 `summary.fme_count`，页面不重算）。\n显示 — 表示接口没给这个字段，**不是 0 个人**；数为 0 通常是该月在 `eflow_wo` 里找不到能归属到榜单站点的工单。',
    'fme.tip.siteCount': '榜单覆盖的站点数（接口 `summary.site_count`）。一行 = 一个站点，所以它等于下方表格的行数；\n可用率为空的站点**仍在榜上**（只是不参与可用率名次）。',
    'fme.tip.woTotal': '工单总数 = **创建时间落在所选自然月内**、且能归属到榜单站点的工单条数：\n时间区间是「月初 ≤ t < 次月初」左闭右开（`month_bounds_exclusive`），时间字段由 `detect_wo_schema()` 在表结构里自动识别（缺失时整块统计为空并回一条 warning）；\n归属优先按 `site_id`，没有 site_id 的行退回**规范化站名**（多空格折叠 + 去首尾空格 + 小写）比对（`norm_name`）。\n所以换个月份这些数会整批变，不是累计。',
    'fme.tip.woOpen': '未关闭条数 = 同一批工单里状态不算已关闭的那些。颜色只区分「有没有」，不代表好坏；\n⚠ 全站「未关闭」有三套判据（这一页按行状态字段判，备件报表按单号去重 + 全词表，仓库看板精确等值），三页的数不该互相对账。',
    'fme.tip.slaRate': '达成率 = (Pass + Within SLA) ÷ (Pass + Failed)。\n⚠ **分母不是本月全部工单**：`sla_status` 为空或其它值的记录两边都不进（`fme_ranking_service.py:118-122`），\n刻意不让「未知状态」拉低达成率 —— 所以下方 `x/y` 的那个 y 才是真分母。\n接口没有可算记录时返回 null，页面显示 —（不显示 0%）；`sla_rank` 也一并不参与（见列头 ⓘ）。',
    'fme.tip.slaFail': 'Failed 条数（与上面那个分母同源）；比率类判据都在后端算，页面只做 ×100 的展示换算。',
    'fme.tip.rank.avail': '首列名次 = `availability_rank`，由后端排：可用率**降序**（#1 = 可用率最高）。\n并列时有两级决胜 —— 先比 SLA 达成率（高者在前），再比 FME 名（`fme_ranking_service.py:255-260`）；没有可用率数据的行不参与名次。\n⚠ 本页三张榜的卡片此前是按数值自己排序的，与这三列的方向/决胜规则对不上过（2026-11-05 起卡片徽章一律用后端 rank，前端不再排）。',
    'fme.tip.rank.wo': '`wo_rank` 由后端排：**按工单数升序，#1 = 名下工单最少**（并列时按 FME 名）。\n所以「WO 最多前三名」那三张卡的徽章是 #41/#42/#43 这类靠后名次，不是 1/2/3 —— 卡片与这张表列同源，前端不再自己排。\n（2026-11-05 修正：此前卡片按工单数降序标 #1，与表列方向相反，同一页会出现两个「第 1 名」。）',
    'fme.tip.rank.sla': '`sla_rank` 由后端排：达成率**降序**（#1 = 达成率最高），且**分母不足 5 条的 FME 不参与名次**（`sla_rank` 为 null，页面显示 —），\n否则「2 单全 Pass」会压过「80 单全 Pass」。可用率名次在 `availability_rank` 列，另有「并列时 SLA 高者在前」的决胜项。',
    'fme.explain.topSla': 'SLA 达成率 = sla_status 为 Pass/Within SLA 的 WO ÷ (Pass + Failed)。样本量不足 5 条的 FME 不参与排名，避免小样本拉高名次。',
    'fme.explain.bottomSla': 'SLA 达成率最低的三名 FME，是本月超时工单需要重点整改的对象。',
