    'msKpi.explain.metDays': 'N/M 天达标 = 该指标**日值达标的行数 / 矩阵里的日行数**。\n分母不是自然月天数 —— 缺档的日子不计数，所以「28/28」可能只覆盖 28 天而非整月。\n达标方向（越高越好 / 越低越好）与判定都由后端给出。',
