    'msKpi.explain.trendStat': 'min / max / avg 只统计**有值的日行**；avg 是这些行的等权算术平均（不按单量加权），\n所以它和卡上的「月值」（工作簿 Month 行）**可以不相等**。',
    'msKpi.explain.overviewCount': '这几张卡统计的是**指标个数**，不是单量也不是天数：\n达标数 = 后端 met 为 true 的指标数；未达标数 = met 为 false 的；**met 为 null（没有目标值）的不计入任何一侧**，所以三个数相加可能小于指标总数。',
    'msKpi.explain.overviewDays': '= 矩阵里的**日行数**，不是自然月天数 —— 报表缺档的那些天不计数。副行给首日 ~ 末日，可据此判断实际覆盖。',
    'msKpi.explain.overviewRate': '取工作簿 Month 行的 Total / Within SLA / Achieve **三列各自的原值**，报表给什么就显示什么。\n所以 Achieve **不一定等于** Within ÷ Total（三者由报表分别算好），对不上时以报表为准，不是本页算错。',
    'msKpi.explain.worst': '= 按**相对目标差距** gap 排序的第一名（lower 类反向算 gap）。\n⚠️ 没有目标值或目标为 0 的指标 gap 记 0，**永远不会进这个榜单** —— 所以「最差」是「有目标且差距最大」，不是「最糟的指标」。',
