    // ---- SP 物料汇总数字悬浮说明（AGENTS.md 三.3c）----
    // 口径对过 backend/services/sp_material_summary_service.py 的 _build_row() / 分桶与消耗推导。
    'spMat.explainCol.anchor': '期初这一组 = **锚点快照日**（anchor_date）当天各分组库存的两列拆分。\n分桶规则：状态为 damage 的进「待修」；否则物料类型含 spare 的进「备件良品」、含 consum 的进「耗材」。\n库存取自 inventory_details 按快照日 SUM(Stock Qty)；归组是 Warehouse Id 精确/前缀 **或** Warehouse Name 含关键词，命中一条即进该组，每组另带排除词（如 1st WH 排除名里含 "2nd floor" 的仓），全都不落才进 Others。',
    'spMat.explainCol.current': '当前这一组 = **当前快照日**（current_date）同一分组、同一分桶规则的库存。\n「消耗」= 某一期初 − 本列当前，所以这一组是三个消耗窗口的公共减数。',
    'spMat.tip.anchor': '{label}：期初快照库存 **{v}**\n归组按 Warehouse Id 精确/前缀 **或** Warehouse Name 含关键词（每组另有排除词），全都不命中才落 Others',
    'spMat.tip.current': '{label}：当前快照库存 **{v}**\n三个消耗窗口都用它作减数',
    'spMat.tip.needRepair': '{label}：状态为 damage 的库存 **{v}**\n它属于「待修」，**不计进**期初/当前那两组的备件良品 + 耗材合计',
    'spMat.tip.repairOutbound': '{label}：报修出库 **{v}**\n⚠ 这一列来自**另一张表**（outband_details 中 Outbound Type = Repair Outbound，一行 = 一个序列号、Qty 恒为 1），且该表只有仓库名没有仓库 ID，归组只按名字 —— 统计窗口也与库存快照不同，不能拿它去减库存列',
    'spMat.tip.consumption': '{label}：该窗口消耗 = **期初库存 − 当前库存** = {v}\n期初合计 {aTotal}、当前合计 {cTotal}（合计只含备件良品 + 耗材，**不含待修 damage**）\n拆分成「备件 / 耗材」两列时两列相加才等于整列',
    'spMat.tip.negative': '⚠ 这里是**负数**：说明期间有入库或调拨回补，库存不降反升。消耗口径只做「期初 − 当前」，**不扣回补**，所以负值合法，后端也会另行落 warning 点名。',
    'spMat.tip.unitIsRows': '单位提醒：这些数都是 SUM(Stock Qty) 的库存数量，不是物料种类数',
    'spMat.tip.drill': '点数字下钻该分组该列的逐物料明细',
    'spMat.tip.modalTotal': '合计 = **当前搜索框筛过的 {n} 行**在数量列上求和（接口不下发这个合计，是前端即时聚合）。\n下钻一共返回 {all} 行；清空搜索框时两者相等。',
    'spMat.warnTitle': '数据提示',
    'spMat.staleBackend': '当前后端服务还是旧版本（未返回 Repair Outbound / 消耗拆分字段），因此这几列显示为 0。请在服务器上双击 fix_backend.bat 重启后端后再刷新。',
    'spMat.docTitle': '统计口径',
    'spMat.doc1': 'Spare Part (Good) = Material Type 为备件且 Material Status 非 damage 的库存数量合计；Consumables = 耗材类库存数量合计。',
    'spMat.doc2': 'Current Date 取库存表最新快照日（见上方标签），期初日期默认取该快照所在自然月 1 号，可手动调整。',
    'spMat.doc3': 'Total Consumption = 期初库存 − 当前库存，按 Spare Part 与 Consumables 分别统计；三个窗口分别为：锚点日、本月 1 号、本周一；出现负值说明期间有入库回补或调拨进仓。',
    'spMat.doc4': 'Need Repair = 当前快照中 Material Status 为 damage 的数量；Repair Outbound = 出库表中「当月 1 号 00:00:00 至今」且 Outbound Type 为 Repair Outbound 的出库件数，按仓库归组。',
    'spMat.doc5': '点击任意数字可下钻：库存列看当日物料明细，消耗列看「期初 vs 期末逐物料对比」，Repair Outbound 看当月报修出库记录。',
