    'siteAvail.explain.monthAvg': '当前制式的月均 = 把**过滤后**每个站点的「本月有值日期算术平均」再取一次算术平均（**站点等权**，不按流量或小区数加权）。\n⚠️ 它只统计搜索框过滤后看到的站点，与后端全量汇总不是同一口径 —— 清空搜索框才是全网值。',
