    'siteAvail.explain.monthTickets': '本月工单(TT) = 按 **created_time** 落在本月的 eflow_tt 行数；橙色「未闭环」= status ≠ Closed。\n每条 TT 先按 site_id 精确匹配、未命中再按规范化站名，**唯一归属一个站点，不重复计数**。',
