    'availSum.explainCol': '可用率 = **SUM(分子) / SUM(分母)**，不是各站点简单平均。\n数据源：派生库 availability_daily（定时任务 avail_recon_sync 每天 06:10 从远端站点日 KPI 近似重建）。\n这一格的分子分母具体是多少，把鼠标停在数字上就能看到。',
    'availSum.explainKpi': '该制式全网可用率 = 主表里区域 **ALL** 那一格：把本期所有（站点 × 天）的可用率按站点-日加权求和后的比值。\n**不是**各区域数字再平均，且**包含**未匹配上站点主数据的站点。\n点卡片下钻该制式明细。',
    'availSum.explainUnmatched': '未匹配占比 = 站点名匹配不上站点主数据（FME_Region 为空）的那批站点，**占本期分母（站点-日观测数）的比例**（实测约 2.3%）。\n它们**计入区域 ALL**，所以 ALL 行 ≠ 各区域相加 —— 这是口径本身，不是数据缺失。',
    'availSum.explainRegionKpi': '该区域可用率 = 该区域本期**全部制式、全部站点类型**合计的 SUM(分子)/SUM(分母)（按站点-日加权），不是几个制式数字再平均。\n本页列出的区域**跟随站点主数据 master_site_db**（当前为 North / South，主数据换了页面自动跟随，代码里不写死）；匹配不上主数据的站点**不在任何区域卡里**（它们单列成「未匹配」行，且计入 avail_ms 的 ALL）。\n点卡片下钻该区域明细。',
