        'msSla.explain.nur': 'NUR = Σ(小区数 × MTTR 分钟) × 60 ÷ (分母小区数 × 期间秒数)，界面按 **×100000** 显示。\n样本只计 0 < MTTR < 43200 分钟（30 天）且已清除的单；小区数按**站名**匹配，未命中回落 site_id。\nGlobal 行是各制式分子相加 ÷ 小区数相加，**不是**几个制式数字的平均。',
