        'msSla.explain.persite': 'PS_* = 该期**阈值达标行数 ÷ 总行数**，逐项阈值不同（如 PS_CSSR_2G ≥0.97、PS_DCR_2G ≤0.02）。\n例外：PS_NUR_2G / PS_NUR_3G 换成「站点 NUR×1e5 < 350 的站点数 ÷ 该制式有小区的站点数」。',
        'msSla.explain.wo': 'Total = 该期单数；Within SLA = sla_status 为 Pass 的单数；Achieve = Pass ÷ Total（后端已算，界面只 ×100 显示）。\nTotal 为 0 时 Achieve **无值**（显示 -），不是 0%。',
        'msSla.explain.color': '颜色按「≥95% 判绿」—— 这是前端唯一的阈值，后端逐项阈值并不相同。\n⚠️ **已知缺陷**：DCR 类指标（2G_DCR / 3G_DCR / 3G_DCR_HSDPA）是**越小越好**，按这条判色会恒红，**颜色不代表达标**。',
        'msSla.explain.ttrSev': '本页 TTR_P1..P4 只是**按严重度分组**，没有 4h / 8h / 16h / 2Days 的时限判定。\n与「MS WO SLA」页的 TTR_P1_4h **同名不同口径**，两页数字不可互相印证。',
