    'alarm.explain.mainsDuration': '与持续时长分布口径一致，但仅统计 transmission_type = "MW"（微波市电中断）的告警。',
    'alarm.explain.tech': '按技术制式分组：由 type 正则 -(\\d+G) 推断，否则由 restypename 推断（ENODEB/GNB→4G, NODEB→3G, BTS→2G）。',
    'alarm.explain.region': '按 2 位区域码（利比里亚 15 个州）分组的告警数；未映射区域 "--" 已排除。\n三量判据各不相同：告警数 = 逐行数；「MW」那一列是 **transmission_type == "MW"** 的行数（后端字段名叫 region_mains_count，判据却是微波传输，命名与含义不一致属已知问题）；站点数 = 该区域内唯一 site_id 的个数。',
