    'alarm.tip.regionAlarms': '{n} = 该区域当前活动告警条数（逐行数）\n其中 transmission_type = MW 的 {mains} 条\n唯一 site_id 的站点数 {sites} 个\n区域码不在 15 州清单里的行**不计入任何区域**',
    'alarm.tip.typeCount': '{region}：该类型 {n} 条\n类型名取 alarm_title，为空时回落 codename\n点这一行下钻该类型全部告警',

