    // 数据总览备注
    'overview.explain.totalTables': '数据库里的**表总数**：接口 `/api/db/info` 逐名列出后取 len()。\n⚠ 这里**不排除**以 `_` 开头的内部表（旧文案说排除了，与实现不符，2026-11-04 已按代码更正）。\n方言两支（`backend/routers/system.py:99-109`）：PG 模式取 `information_schema.tables` 里 `current_schemas(false)` 的 **BASE TABLE**（视图不计），名字带 schema 前缀如 `app.eflow_tt`；SQLite 模式取 `list_table_names`，只排除 `sqlite_%`。',
    'overview.explain.totalRows': '所有表行数的**合计**：后端对每张表逐条执行 `SELECT COUNT(*)` 再相加（`system.py:110-118`）。\n是实测值，不是 `pg_class.reltuples` 之类的估计值；无任何时间/状态过滤，也不排除内部表与归档表。\n所以「总行数」把 `_` 前缀表、`analysis_archive`、`uploaded_files` 都算进去了 —— 下面的 Top10 却排除了它们，两边对不上是口径不同，不是丢数。',
    'overview.explain.coreTables': '「核心表数」= 前端在接口下发的表清单上数**名字不以 `_` 开头**的表（`Overview.tsx` 的 filter+length，接口不下发这个字段）。\n⚠ PG 模式下表名带 schema 前缀（`app.xxx`），这个判据基本恒为真 → 核心表数 = 表总数；只有在 SQLite 模式下才会真正滤掉 `_` 开头的表。',
    'overview.tip.totalTables': '本数 = 接口 total_tables = **{n}**（后端列出表名后的条数）\n不排除 `_` 前缀内部表；PG 只数 BASE TABLE（视图不算），SQLite 只排 `sqlite_%`',
    'overview.tip.totalRows': '本数 = 接口 total_rows = **{n}**\n算法：对每张表逐条 `SELECT COUNT(*)` 再相加 —— 实测值，不是统计估计\n含 `_` 前缀内部表与归档/上传表，所以它**大于**下方 Top10 各行之和（那一张排除了这些表）',
    'overview.tip.coreTables': '本数 = **{core}**，由前端在接口下发的表清单上数「名字不以 `_` 开头」的表得到（接口不下发这个字段）\n表总数 {all}：两者之差就是 `_` 前缀的内部表数\n⚠ PG 下表名带 `schema.` 前缀，这个判据几乎总为真 → 两数相等属正常现象',
    'overview.tip.status': '这一张不是算出来的数字：接口成功返回就显示「正常」，失败时整页转为错误态\n它只说明 `/api/db/info` 这一次调用通了，不代表各表数据新鲜（新鲜度看「任务管理」）',
    'overview.explain.rank': 'Top10 是**前端排的**：接口下发的 `tables` 不排序也不截断，页面先滤掉 `_` 前缀、`analysis_archive`、`uploaded_files`，再按行数降序取前 10（`Overview.tsx:40-43`）。\n柱上的数 = 该表 `SELECT COUNT(*)` 的实测行数。\n⚠ 所以「Top10 之和 ≠ 页头总行数」：后者含被这里排除的内部表与归档表。',
    'overview.explain.dist': '这张饼图与左边的柱图**同一份筛选后的集合**（同样排除 `_` 前缀 / `analysis_archive` / `uploaded_files`）的前 10 名。\n百分比由 ECharts 按**这 10 张表的行数之和**算，不是全库占比 —— 所以它们相加是 100%，却不等于「这 10 张表占全库的比例」。',

    // GIS 地图备注
    'gis.explain.note': '历史模式：按 alarm_occur_time 聚合 TT/WO，时间窗结束为排他（+1 天）；仅含经纬度非空且非 0 的站点。\n实时模式：仅展示存在 ≥1 条实时告警的站点（无时间过滤）；超时判定为 (当前时间 − servertime) > assign_delay（此处无 1.1 容差）。\n标记大小由 tt_count + wo_count 决定（>50→10, >20→8, >5→6）。',

    // 分析仪表盘备注
    'dashboard.explain.note': '图表由所选表的字段画像自动生成（分布 / 均值对比 / 趋势 / 质量雷达 / SLA·状态热力图），非固定 KPI。\n⚠ 所有图都算在**最多 10000 行的样本**上：后端取数写的是 `SELECT * FROM 表 LIMIT 10000`（`routers/analysis.py:60`，无 ORDER BY，即按存储顺序取前 1 万行）。\n因此下拉框里显示的「N rows」是全表 `COUNT(*)`，而图里的计数/均值只代表这 1 万行 —— 大表上两者相加必然对不上，不是丢数。\n联动筛选：点击饼图/柱图扇区可下钻过滤同列数据 —— 那是**前端本地高亮**，不会重新取数，点完看到的数字仍是全样本口径。',
    'dashboard.explain.pie': '饼图 = 该列 `value_counts().head(10)`（`analysis.py:237`）：**只取出现次数最多的前 10 个取值**。\n扇区百分比由 ECharts 按**这 10 个取值之和**算 —— 第 11 名及以后的取值根本不进分母，所以「100%」不等于「该列全部行数」。\n计数同样是在 ≤10000 行样本上数的。',
    'dashboard.explain.bar': '柱图 = 按类别列 `groupby().mean()` 后 `dropna().head(15)`（`analysis.py:271`）：每类取**数值列的算术平均**，不是求和，也不加权。\n⚠ 后端把 NaN 落成了 0（`analysis.py:280` 的 `else 0`），所以柱子上的 0 可能是「真的 0」也可能是「该列没有可算的数值」。\n类别只展示前 15 个；均值算在 ≤10000 行样本上。',
    'dashboard.explain.line': '折线 = 按日期列 `groupby().size()` 后 `tail(60)`（`analysis.py:300`）：纵轴是**该日的行数计数**，不是任何指标的和或均值。\n只保留最近 60 个日期；计数算在 ≤10000 行样本上，样本若被 LIMIT 截断，靠后的日期会偏少。',
    'dashboard.explain.radar': '雷达 = 每个数值列的质量分 `score = 100 − 空值率 − min(问题数 × 10, 50)`，负数截为 0（`analysis.py:309-310`）。\n空值率 = 样本内 `isna / 行数 × 100`（`services/profiler.py:58`）；问题数来自字段画像的 issues_summary。\n刻度上限 100 是前端写死的；这是一把**启发式尺子**，不是业务达标率。',
    'dashboard.explain.heat': '热力图 = `pd.crosstab(类别列, SLA/状态列).head(15)`（`analysis.py:324-331`、`:354-361`）：格子里是**该组合的行数计数**，只画前 15 个类别。\n⚠ 空组合后端落成 0（`else 0`），色阶上限由前端 `Math.max(...)` 现算，不代表全表最大值。',
    'dashboard.explain.other': '这张图的数值同样算在**最多 10000 行的样本**上（`SELECT * FROM 表 LIMIT 10000`，无排序），与下拉框显示的全表行数不是同一个分母。',
    // 图内数字在 canvas 里包不住气泡，口径改挂到 ECharts tooltip 末行（短句，逐条字面量键）
    'dashboard.tip.pie': '计数与百分比都算在 ≤10000 行样本上；百分比的分母是图上这 10 个取值之和',
    'dashboard.tip.bar': '柱子是该类别的**均值**（不是和、不加权）；NaN 记为 0；样本 ≤10000 行',
    'dashboard.tip.line': '纵轴是该日期的**行数计数**（不是任何指标的和/均值）；样本 ≤10000 行',
    'dashboard.tip.radar': '质量分 = 100 − 空值率 − min(问题数×10, 50)；启发式，上限 100 前端写死',
    'dashboard.tip.heat': '格子是**该组合的行数计数**（样本 ≤10000 行）；空组合记 0',
    'dashboard.tip.other': '数值算在 ≤10000 行样本上（后端取数无排序，非全表）',

