    'table.mwCurrent': '当前数据库中的数据：',
    'table.mwSites': '站点 {n}',
    'table.explain.rowCount': '= 接口 /tables 对该表执行 `SELECT COUNT(*)` 的**全表行数**：不带时间窗，也不受下方搜索框与筛选影响。注意本地权威表（数据只写本地 SQLite 的那几张）在 pg 模式下读的是主库里的同名空表，恒 0 行 —— 页内已常驻说明。',
    'table.explain.colCount': '= 接口 /tables 返回的表结构列数。画像页签里的 total_cols 是同一含义，但那是按**采样后的 DataFrame** 数的。',
    'table.explain.visibleCols': '当前显示 {n} / 共 {m} 列。n = 你在「自定义列」里勾选的列数，m = 接口返回的总列数。这只是**显示层**过滤，不改变任何行或列的计数。',
    'table.explain.pageTotal': '= 接口 data 端点的 total = **带当前搜索条件**的 COUNT(*)，不是全表行数。搜索是全列 LIKE 模糊匹配：非文本列先 CAST 成文本，且最多只看前 200 列（宽表超出部分不参与匹配），所以「搜出 0 行」不等于「数据不存在」。',
    'table.explain.importRows': '= 接口返回的 row_count = 本次导入**写入数据库的行数**（Excel 的数据行，不含表头）；col_count = 解析出的列数。覆盖导入时它是覆盖后的总行数。',
    'table.explain.quality': '质量分 = 100 −（问题数 ÷ 检查项数）× 100，检查项按**每列 5 项**写死，而单列最多只能触发 4 项（离群值 / 空值率 / 单一值列 / 分布倾斜），所以分数下限是 20，保留 1 位小数。空值率 >50% 记严重、>20% 记警告（互斥）。',
    'table.explain.sampleRows': '这个 {n} 是**采样行数**：后端画像 SQL 写死 `SELECT * LIMIT 10000` 且不带 ORDER BY，取的是数据库先返回的前 1 万行，不是随机抽样。全表行数看页头那个行数 Tag。',
    'table.explain.sampleCols': '= 接口 total_cols：采样 DataFrame 的列数。后面所有画像指标（空值率、唯一值数、质量分）都基于**同一份 ≤1 万行样本**。',
    'table.explain.issueListLen': '= 前端取 profile.issues_summary 的**数组长度**：后端逐列检测后汇总的问题条数。一列可能贡献多条，所以它不等于「有问题的列数」。',
    'table.profileSampled': '画像基于**前 {n} 行采样**（后端 SQL 写死 LIMIT 10000，无 ORDER BY，非随机）：质量分、空值率、唯一值数只反映这份样本。全表行数请看页头的行数标签。',
    'table.explain.colNullRate': '该列空值率 % = 接口 null_rate = null_count ÷ total × 100，分母 total 是**采样行数**。颜色阈值（>50 红、>20 黄）只是显示强调，不代表业务判定。',
    'table.explain.cellNullRate': '{name}：接口 null_rate = {pct}%，即 {nulls} ÷ {total}（采样行数，不是全表行数）。',
    'table.explain.colUnique': '该列唯一值数 = 接口 unique_count（pandas nunique，**不统计空值**）。要和空值率合看：一列 90% 为空 + 少数几个值，unique 很小但并不代表数据好。',
    'table.explain.cellUnique': '{name}：接口 unique_count = {uniq}，采样行数 {total}。',
    'table.explain.colIssue': '该列问题数 = 接口 issue_count，取值来自四类检测（离群值 / 空值率 / 单一值列 / 分布倾斜）里命中的条数，一列最多 4 条。徽标只在这个数 > 0 时出现。',
    'table.explain.cellIssue': '{name}：接口 issue_count = {n}，具体条目在 profile.issues_summary 里逐条给出（本端点不截断，与上传页那份「只列前 10 条」不同）。',
