    'sync.statHint': '点击状态卡片筛选任务，再次点击或点击“全部”取消筛选',
    'sync.explain.cardAll': '= 接口 /tasks 一次返回的任务行数（后端以 TASK_SPECS 注册表为准，**含已停用的任务**）。本页不再过滤。',
    'sync.explain.cardRunning': '「进行中」= 前端轮询的 /tasks/running（队列与内存态）命中，或本页刚点过「执行」的本地标记 —— **不看**数据库里的执行记录，所以刷新瞬间可能比实际少。',
    'sync.explain.cardSuccess': '「成功」= 该任务**最新一条**执行记录 success=true（后端按 MAX(id) 取 recent_runs 的第一条）。它不代表近 N 天都成功。',
    'sync.explain.cardFailed': '「失败」= 最新一条执行记录 success=false，且当前不在运行。看的是**最近一次**，不是窗口内的累计失败次数 —— 累计次数在「失败聚合」弹窗里。',
    'sync.explain.cardDisabled': '「停用」= 接口返回 enabled=false。实际启停由表 task_schedule_config 覆盖 TASK_SPECS 的默认值，改完即时生效、不用重启。',
    'sync.explain.cardUnknown': '「未记录」= 任务已启用但库里**没有任何执行记录**（新登记或从未跑过）。刻意单列一张卡：缺了它，各状态卡之和会小于「全部」，会被读成统计错。',
    'sync.explain.cardSum': '每个任务恰好归入一桶（判定与筛选共用同一函数），所以五张状态卡之和 = 「全部」{all}。点卡片即切筛选，卡上的数字与筛选结果同一判定。',
    'sync.explain.toggleCount': '分子 {enabled} = 列表里 enabled 的任务数；分母 {all} = 接口返回的全部任务行数（**含豁免与手动停止的**，所以列表 {all} 行就报 x/{all}）。开关本身的判定只看非豁免、非手动停止的任务，与这个分母刻意不同 —— 否则又会踩「怎么点都关着」那个坑。',
    'sync.explain.listCount': '分子 {shown} = 当前筛选后的行数，分母 {all} = 接口返回的全部任务行数；两者刻意不同口径。',
    'sync.explain.failBanner': '横幅的 N = {count}，含义是「最新一条执行记录失败、且当前不在运行」的**任务数**（与「失败」状态卡同一判定）。按任务计，不是失败次数。',
    'sync.explain.groupCount': '括号里的 {n} = 该分组在当前筛选下渲染出来的任务卡片数；分组本身来自接口字段，本页不再过滤。',
    'sync.explain.timelineCount': '= 时间轴上有执行记录的任务数 {n}（接口从未返回执行记录的任务不上轴）；任务总数是 {all}，两者差值即「未记录」那张卡的数字。',
    'sync.explain.elapsed': '= 接口最近一条执行记录的 elapsed_seconds（秒，保留 1 位小数）。显示 — 表示这条记录没有耗时字段，**不是**跑了 0 秒。（任务 id={id}）',
    'sync.explain.aggTotal': '近 {days} 天「共 {n} 次失败 / {k} 类根因」：接口 /tasks/failures 取该窗口内 success=0 的记录，按**错误信息首行**归并成簇；{n} = 各簇计数相加，{k} = 簇数。',
    'sync.aggTruncated': '⚠ 接口 SQL 只取最近 {scanned} 条失败记录（近 {days} 天，取满即可能还有更久的没扫到）—— 上面的「共 N 次失败」是**至少** N 次，不是窗口内的真实总数。',
    'sync.explain.clusterCount': '×{n} = 这一簇（错误首行「{first}」）在本次取回的记录里出现的次数，取接口 clusters[].count。',
    'sync.explain.taskFailCount': '{tid} ×{n} = 该任务在这簇里的失败次数（接口 clusters[].tasks 映射）。点这个标签会直接打开该任务的执行历史。',
    'sync.explain.thTotal': '总运行 {n} = 接口 stats 的 COUNT(*)（该任务在 task_execution_log 里的全部记录），其中成功 {ok} / 失败 {bad}。这张表默认只保留 7 天（环境变量 TASK_LOG_RETENTION_DAYS 可调），所以它不是「上线以来」的总数。',
    'sync.explain.thSuccess': '成功率 {rate} = 成功次数 ÷ 总运行次数（同表同任务的全部保留记录）。绿色阈值 0.8 只是**前端的显示配色**，不是业务达标线。',
    'sync.explain.thAvg': '平均耗时 {v} = 接口 AVG(elapsed_seconds)：保留记录里每次运行的算术平均，**含失败的运行**。',
    'sync.explain.thMax': '最大耗时 {v} = 接口 MAX(elapsed_seconds)：单条记录的实际耗时，与超时设置无关。',
