    // Packet Loss metric explanations
    'pl.explain.totalSites': '被纳入丢包监控的站点总数。\n数据来源：Packet Loss Status Report 的站点主数据（lte_pl.sqlite3，最近 7 个完整自然日逐小时粒度；当天未过完的数据不展示）。',
    'pl.explain.critical': 'FINAL_STATUS 判为 Critical 的站点数。\n计算：先按 0~23 标志块判 STATUS（最近 3 天同整点丢包均 >0.5% 记 1，标志全 0 则 OK）；STATUS≠OK 且 Last 1 day Max PL ≥ 5% 判为 Critical。\nLast 1 day Max PL = 最近完整一天（00~23 点）逐小时丢包率的最大值。',
    'pl.explain.major': 'FINAL_STATUS 判为 Major 的站点数。\n计算：STATUS≠OK 且 Last 1 day Max PL 落在 [1%, 5%) 区间判为 Major。',
    'pl.explain.minor': 'FINAL_STATUS 判为 Minor 的站点数。\n计算：STATUS≠OK 且 Last 1 day Max PL 落在 [0.5%, 1%) 区间判为 Minor。',
    'pl.explain.warning': 'FINAL_STATUS 判为 Warning 的站点数。\n计算：STATUS≠OK 且 Last 1 day Max PL 落在 [0.1%, 0.5%) 区间判为 Warning。',
    'pl.explain.noPacketLoss': '视为正常的站点数。\n计算：STATUS=OK（0~23 标志全为 0，即不存在最近 3 天同整点丢包均 >0.5% 的整点）强制归一为 No Packet loss；或 STATUS≠OK 但 Last 1 day Max PL < 0.1%。',
    'pl.explain.affectedSites': 'Affected Sites = Critical + Major（即 STATUS≠OK 且 Last 1 day Max PL ≥ 1% 的站点数）。\n与 Excel 报告 Summary 表的 Affected Sites (Critical+Major) 口径一致，不含 Minor/Warning。',
    'pl.explain.granularity': '数据粒度：最近 7 个完整自然日逐小时（SDR + IPRAN 的 IPPD 丢包率）；当天未过完，其数据不展示。\nSTATUS 口径：最近 3 天同整点丢包均 >0.5% 的整点记为标志 1，标志全 0 -> OK，否则 NOK。\nSDR = 软定义无线（3G/2G）；IPRAN = IP 化回传承载网。',
    // ---- 数字悬浮说明补齐（2026-11-04，AGENTS.md 三.3c）：口径从 routers/packet_loss_dashboard.py 核实 ----
    'pl.explain.dist': '这三张图的**分母不是同一个集合**，别互相核对：\n· 状态饼图 = site_pl_summary 逐行按 FinalStatus 计数（含无坐标站点）；扇区百分比由 ECharts 按**当前显示的扇区之和**算 —— 用图例隐掉某一档后，百分比会跟着重算，与后端下发的 pct（分母恒为全部站点）不再相等。\n· 区域柱图 = **只统计非 OK 站点**（含 Minor/Warning），所以它的站点数合计 **大于**顶部「Affected Sites = Critical + Major」。\n· 每日趋势的中位数**只取当天 >0 的读数**：逐小时丢包约 59% 是 0，全量取中位会被压成 0 而失去意义；「受影响站点」按 >0.1% 去重 Managed Element 计数，窗口只保留最近 7 个完整自然日（当天不展示）。',
    'pl.explain.topSites': 'Top 站点：窗口 = **最近 24 个完整整点**（剔除当天），每站点取其全部读数的中位数（**含 0**），按 code→name 关联后排序取前 15。\n为什么趋势用「非零中位」而这里用「含 0 中位」：站点级若也只算非零，「半天正常半天全断」与「整天全断」都会得 100，失去区分度（`packet_loss_dashboard.py:192-238`）。\n受影响小时数 = 窗口内丢包 >0 的整点个数；两者口径不同，不能相除。',
    'pl.tip.drillCount': '当前 **{n}** 行 = 明细在**搜索框筛过之后**的行数；接口本次下发 {total} 行。\n⚠ 接口按上限取回明细，{total} 已是截断后的条数 —— 所以「这里的行数」不等于「该状态的全部站点数」，需要全量请缩小筛选范围或看导出。',

