    // ---- 数字悬浮说明（2026-11-05，AGENTS.md 三.3c）----
    'batt.clientCalcNote': '⚠ 这张卡是**前端在页内筛选后的行上现算**的。接口 `/api/battery-dashboard/all` 也下发同名 `kpi` 字段，\n但那是**不带任何筛选的全量值**（实测未筛选：接口总数 1532 / 站点 208，卡上在「仅新鲜」下是 352 / 48）。\n两边不等通常是**筛选正在生效**，不是数据错 —— 2026-11-05 逐值对拍过：除「总数」「站点数」是两套语义、\n均值差在小数位数（前端留 1 位、接口留 2 位）之外，其余六项与五种分布逐桶相等。\n保留前端计算是刻意的选择（经用户确认）：页内六个筛选器要即时联动，改读接口会让卡片不随筛选变化。',
    'batt.explain.socDist': '分桶判据**写死在前端**：≤0 → 空、<20 → 危急、<50 → 低、<80、≥80（`BatteryDashboard.tsx:240-242`）。\n⚠ 它不跟可配阈值联动：上面「SOC 危急」那张卡用的是接口下发的 `meta.soc_critical`（改了配置会跟着变），\n而这张图的桶边界与桶标签都不会变 —— 同一页上两个「20%」来源不同，别把它们当成同一个数。\n样本集合由「仅新鲜」开关决定（开着时只算 24 小时内的读数）。',
    'batt.explain.healthDist': '分桶边界取自接口阈值（`health_degraded` 默认 90、`health_good` 默认 95），\n但**桶标签文字是写死的**（`80-90% (Degraded)` / `90-95% (Fair)`，`:243-245`）。\n⚠ 一旦有人改了阈值，标签与实际区间就会不符 —— 以这句里的判据为准，不要信标签。\n`No Data` 是健康度为空的电池（实测占多数，所以这张图的差异主要在无数据项，不在电池本身）。',
    'batt.explain.statusDist': '非 `Charge` / `Discharge` 的读数一律归进 `Unknown`（`:290-291`），它不代表"未知设备"，只代表状态字段不是这两个词。\n样本集合与 SOC / 健康度分布一样由「仅新鲜」开关决定；`放电中` 常被读成市电中断的代理指标，但它是**当前状态快照**，不是"曾经放电过"的次数。',
    'batt.explain.freshDist': '这张图统计的是**全部行**，不随「仅新鲜」开关收窄（与上面三张分布不同）。\n时效判据在**入库时**就算好了：`last_update` 取三个测量点 updateTime 的最大值，≤24h → fresh、≤7d → delayed、>7d → stale、无时间戳 → no_data\n（`battery_kpi_service.py:197-209`）；三个阈值可被 battery_meta 覆盖，所以「24 小时 / 7 天」是**默认值不是硬编码**。',
    'batt.tip.alarmBadges': '三枚徽标 = 接口下发的 `alarms` 列表在**当前筛选出的站点集合**上重新数的条数（`:329-334`）。\n⚠ 接口另下发 `alarm_summary`，那是**不随筛选变化**的全量数（实测未筛选时与这里一致）；两边不等通常是筛选生效中。\n告警共七类判据（SOC<20、健康<90、超 7/30 天未更新等）在 `battery_dashboard.py:152-204`；\n告警列表有 2000 条上限（`:377`），命中上限时这里的计数会偏小。',
