    // 口径说明整体默认收起（AGENTS.md 三.3），标题即展开入口
    'cnkpi5.note.title': '数据口径说明（点此展开）',
    'cnkpi5.note.sec.granularity': '① 粒度：5 分钟与 15 分钟混用',
    'cnkpi5.note.sec.empty': '② 空卡片的原因',
    // 卡片右上「今日 vs 昨日」波动标签：昨天只截到今天最后一个点的同一时刻，
    // 否则「不完整的今天」对比「完整的昨天」会虚低（当日截断效应）
    'cnkpi5.vsDay1': 'vs 昨日 {{pct}}',
    'cnkpi5.vsDay1Hint': '截至 {{time}} 的均值对比：今天 vs 昨天同一时段（昨天截到同一时刻），已剔除「当天还没过完」的影响；波动在 ±10% 内视为正常，超出则以橙色提示。',
    'cnkpi5.vsDay1NoBase': 'vs 昨日 —',
    // ---- CN KPI 5 分钟：组件卡与页头统计的数字悬浮说明（AGENTS.md 三.3c）----
    // 每条与 services/cn_kpi_5mins_service.py 的 WIDGETS value_expr 逐条对过；改 SQL 必须同步改这里。
    'cnkpi5.explain.common': '三条线的日切与 x 轴都取 `substr("End Time", …)`（不是 Begin Time）：Day0 = 今天、Day1 = 昨天、Day7 = 7 天前（同一个星期几）。\n窗口只取这**三个日子**，不是连续 7 天；聚合是 GROUP BY (HH:MM, Day)。\nDay7 有没有线取决于库里攒够 8 天没有，与本页无关。',
    'cnkpi5.explain.emptyCard': '这张卡没有曲线，是因为接口给该组件下发 empty（不是报错）。原因：{reason}',
    'cnkpi5.explain.vlr': '值 = SUM("Number of Subscribers in VLR") —— 同一 5 分钟窗口内的 VLR 用户数求和，单位「个」。',
    'cnkpi5.explain.voice': '值 = ROUND(SUM("Seized Traffic(Erl)"), 2) —— 话务量求和，单位 Erl，保留 2 位。',
    'cnkpi5.explain.dataSub': '值 = ROUND(SUM(GSM + UMTS + EPS 三类「平均附着用户数」), 0)：三列先在同一行内相加再求和，缺列按 COALESCE(...,0) 计 0。',
    'cnkpi5.explain.4gTraffic': '值 = ROUND(SUM("Byte of downlink data packets received via SGi interface per APN(Byte)") / 1e9, 3) —— 字节按 1e9 换算成 **GB**（不是 GiB），保留 3 位。',
    'cnkpi5.explain.rg30': '值 = ROUND(SUM("Bytes of flows of downlink packets based RG(Byte)") / 1e9, 3)，且只取 **"Measurement Object" = 30** 的行。RG-30/12/11/6 四张卡是同表按编号拆开，互不重叠。',
    'cnkpi5.explain.rg12': '值 = ROUND(SUM("Bytes of flows of downlink packets based RG(Byte)") / 1e9, 3)，且只取 **"Measurement Object" = 12** 的行。RG-30/12/11/6 四张卡是同表按编号拆开，互不重叠。',
    'cnkpi5.explain.rg11': '值 = ROUND(SUM("Bytes of flows of downlink packets based RG(Byte)") / 1e9, 3)，且只取 **"Measurement Object" = 11** 的行。RG-30/12/11/6 四张卡是同表按编号拆开，互不重叠。',
    'cnkpi5.explain.rg6': '值 = ROUND(SUM("Bytes of flows of downlink packets based RG(Byte)") / 1e9, 3)，且只取 **"Measurement Object" = 6** 的行。RG-30/12/11/6 四张卡是同表按编号拆开，互不重叠。',
    'cnkpi5.explain.xgwLicense': '值 = ROUND(AVG("Throughput Usage(%)"), 2) —— 是**百分比的算术平均**，不是加权平均也不是峰值。\n⚠ 上游该模板只有 **15 分钟**档（无 5 分钟粒度），所以点位数约为其他组件的 1/3，**稀疏点不是缺数**。',
    'cnkpi5.explain.xgwCpu': '值 = ROUND(AVG("Peak usage ratio of UP\'s vCPU(%)"), 2) —— 每行本身已是「峰值 vCPU 使用率」，这里再对 15 分钟行取**算术平均**（不是取最大值）。\n⚠ 15 分钟档，点位数约为其他组件的 1/3。',
    'cnkpi5.explain.3gTraffic': '值 = ROUND(SUM("Bytes of downlink data packets received via Gi interface per APN(Byte)") / 1e9, 3) —— 字节换算成 GB。\n⚠ 3G 的列名是 **Bytes（复数）**，与 4G 的 "Byte …" 不同；写错时 SQLite 不报错而是把双引号标识符当字符串字面量，SUM 恒为 0（2026-10-19 实测踩过）。\n⚠ 15 分钟档，点位数约为其他组件的 1/3。',
    'cnkpi5.tip.vsFrontend': '这个百分比是**前端**从接口 rows 现算的（接口不下发 pct）：今天 00:00→此刻的均值 与 昨天截到同一时刻的均值 相比。',
    'cnkpi5.tip.vsNoBase': '不显示是因为缺少可比基线：今天或昨天在该时段没有任何点，或昨天该时段均值为 0（除不尽）。',
    'cnkpi5.tip.summary': '{{ok}}/{{total}} = 有数据的组件数 / 组件总数（接口 meta.count）。**空态与失败都不计入**「有数据」。',
    'cnkpi5.tip.elapsed': '{{ms}}ms = 后端并发取这 11 个组件的总耗时（走远端只读 API，不是本机 SQLite）。\n缓存状态：{{cached}}（TTL 30 秒，命中时几乎不耗时）。',
    'cnkpi5.tip.cachedYes': '本次是缓存命中',
    'cnkpi5.tip.cachedNo': '本次是实取（30 秒内的下一次点击会走缓存）',
    'cnkpi5.tip.failed': '{{n}} = 接口 meta.failed：**查询报错**的组件数（空态不算）。多数是远端表尚未生成或超时，具体看对应卡片里的红字。',
    'cnkpi5.exportSource': '数据源',
    'cnkpi5.exportGenerated': '导出时间',

