    // ---- 数字悬浮说明（AGENTS.md 三.3c）：口径逐条从 bm_meta_caliber.py / bm_meta_service.py 核实 ----
    'bmm.explain.verdict': '结论只回答一件事：**区间内谁的速率均值更高**。\n领先分差 = 两家综合评分相减；胜场/配对天数来自逐日比较（两家当天都有数据才算一场）。\n⚠ 本页的「综合评分」**只由速率一项决定**（`SCORE_WEIGHTS = {speed: 1.0}`，caliber:92），网络侧 KPI 不参与 PK —— 别把它读成「综合网络质量分」。',
    'bmm.tip.lead': '分差 {n} = 两家综合分相减（ORANGE {o} − MTN {m}，或反向）\n**这个减法在前端算**：接口只下发两个 score，score 本身由后端算\n分数是相对分（强者恒 100），分差不对应绝对速率差',
    'bmm.tip.verdictWins': '{brand} 胜 {w} 天 / 配对 {d} 天 = {r}%\n配对天数 = 逐日比较里**分出胜负**的日子；平局与任一家缺数据的日子**都不进分母**（与 Speedtest 页不同，那里平局仍进分母）\n本区间平 {ties} 天、共 {total} 天有记录\n点它下钻这些胜日。⚠ 下钻是「先按 3000 行上限取数、再在 Python 里筛胜者」（`bm_meta_service.py:419-423`），所以只有当区间行数超过上限时行数才会少于 {w}；本表一天一行，日常区间远不到上限',
    'bmm.explain.scores': '评分只有**速率**一项（`SCORE_WEIGHTS = {speed: 1.0}`）：领先的一方恒为 100，另一方按 较小值 ÷ 较大值 × 100 得分；完全相等则两家各记 50。\n所以这张卡就是「速率相对分」，**不含网络侧 KPI**，也不含覆盖率。\n点分数卡下钻该品牌的胜日（同样受下面「下钻行数」那条限制影响）',
    'bmm.tip.score': '{brand} 综合分 = **{score}**（另一家 {other}）\n算法：只比速率 —— 自家 {v} 对比另一家 {otherV}，强者记 100，弱者按 较小 ÷ 较大 × 100\n胜场 {w} 天来自逐日比较（平局与缺数据日不进分母）\n⚠ 这张卡不含网络侧 KPI',
    'bmm.explain.speed': '速率均值 = SQL `AVG(orange_liberia | mtn_liberia)`，按区间取数（左闭右开）\nAVG 自动**跳过 NULL**：某家当天没数据就不参与该家的均值\n⚠ 区间行数 days 是**整表在区间内的行数（两家同一个数）**，不是该家自己的有数据天数',
    'bmm.tip.speed': '{brand} 速率均值 = **{v}**\n算法：AVG(该家的原始列)，跳过该家缺数据的日子\n区间共 {days} 行（两家同一个数，不代表该家真的有 {days} 天数据）\n最小 {min} / 最大 {max}；另一家均值 {other}\n点卡片下钻该品牌的胜日',
    'bmm.explain.range': '区间 = 该家在区间内原始列的 MIN ~ MAX（SQL 直接取，不排序不去极值）\n所以它包含单日尖峰：均值看着平稳也可能有一两天的极值很高',
    'bmm.tip.range': '{brand}：最小 **{min}** ~ 最大 **{max}** Mbps\n均值 {avg}（同一批行里算出来的，极值不参与均值之外的处理）\n取自区间内 {days} 行（AVG/MIN/MAX 都自动跳过 NULL）\n点卡片下钻该品牌该区间的全部逐日记录',
    'bmm.tip.network': '{metric}：{hint}\n本区间均值 **{v}**，最小 {min} / 最大 {max}，取自 {days} 行\n这些列**不参与两家 PK**（评分只看速率），也不区分归属 —— 它们是整个 FDD 网络侧的读数{ratio}',
    'bmm.tip.ratioNote': '；比率类列后端已把小数 ×100（0.1956 → 19.56），页面只补百分号',
    'bmm.explain.trend': '实线 = 逐日原始读数（两家 PK 指标取 orange/mtn 两列；网络侧指标取该列的单值）\n虚线 = **最近 {n} 个「非空点」的算术平均**：缓冲区只装非空值并按点数裁剪（`bm_meta_service.py:352-358`），**不是日历窗口**，数据稀疏时这条线会比按天算的更跟手\n均值由后端算好下发（orange_ma / mtn_ma / value_ma），前端不再算第二次',
    'bmm.tip.drillCount': '当前 **{n}** 行 = 接口 returned={returned}（上限 limit={limit}，本次{truncated}）\n取数区间 {range}（左闭右开）\n⚠ 从「胜场」入口进来时：后端**先按上限取行、再在 Python 里筛胜者**（`bm_meta_service.py:419-423`），因此只有区间行数超过 {limit} 时，这里的行数才会少于卡片上的胜场天数；本表一天一行，日常区间远不到上限',
