    'bp.tip.ratioCell': '{period}：BP {bp} ÷ 全网 {total} = **{pct}**\n明细侧该期有 {detail} 行，与展示值差 {diff}（差非 0 = 上游两张 sheet 本就不一致）\n占比是汇总表原值，不是这一行现算的',
    'bp.explain.latestBp': '最新一期 = 当前粒度下**最后一个周期**的 BP 小区数（bp_overall_daily / week / month 三张表按粒度切换）。\n判定阈值：吞吐 < 3 Mbps 且 PRB > 0.80；周要求 7 天里 ≥4 天成立、月要求完整周里 ≥3/4 成立（口径版本 bp-v3）。',
    'bp.tip.latestBp': '{period}：BP **{bp}** / 全网 {total} = {pct}\n这是**单期**的数，不是区间累计\n点卡片下钻该期全部 BP 小区明细',
    'bp.explain.periods': '期数 = 所选区间在该粒度下**实际有数据的周期个数**（一行一个周期），不是自然周期数。\n日粒度看的是有记录的日期条数，周/月同理。',
    'bp.tip.periods': '本区间共 **{n}** 个{grain}周期\n点它滚到下方趋势明细表逐期看（期数不是小区级指标，没有对应的下钻行）',
    'bp.explain.avgRatio': '⚠ 平均占比 = **各期占比的算术平均（每期一票，AVG(bp_ratio)）**，**不是** ΣBP ÷ Σ全网。\n所以它和下方「区间合计」算出来的比率**天然不等** —— 小区数少的期与多的期在这里一样重。',
