    'ipt.note.title': 'Data caliber notes',
    'ipt.note.source': 'Source & frequency',
    'ipt.note.sourceBody': '**IPT Digital Platform** (RMS energy monitoring, external SaaS). Collector task ipt_power_collect runs every **2 minutes**: one filter-map request refreshes all ~500 sites\u2019 connectivity; full_kpi concurrently fetches the lightweight **popup KPI** for every site (501 sites in 60s measured) so **every site gets a snapshot every 2 minutes** (load / battery voltage / SOC / solar / diesel / active alarms); full_shard concurrently fetches the full **diagram detail** (\u226460 sites per round, ~15s, all sites covered in ~20 min, watch sites every round) feeding generator phase voltage, battery capacity, fuel tank capacity etc. The upstream has no bulk power endpoint \u2014 2-min full-site resolution is achieved by 32-thread concurrent per-site polling (measured 2026-11-04).',
    'ipt.note.watch': 'Watch sites & detail coverage',
    'ipt.note.watchBody': '\u26a1 icon = watch site (full diagram detail every round). Config: backend/services/ipt_data/watch_sites.json (sites = watch sites, full_kpi = all-site popup tier, full_shard = diagram detail rotation; **do NOT set "*" in sites**). "Refresh now" queries the platform live regardless of the rotation and adds a snapshot + detail immediately.',
    'ipt.note.retention': 'Retention & nulls',
    'ipt.note.retentionBody': 'Snapshots are kept for **2 days** and pruned automatically. Popup rows store no raw JSON (volume control: 501 sites \u00d7 720 rounds/day); the diagram detail is kept per site as the latest row in ipt_power_site_detail. Fields not reported upstream show "-"; **solar**: sites without solar equipment show "-", sites with equipment read 0 W at night (local ~18:30\u201306:30) which is normal; **offline sites** may stay at their last pre-offline values.',
    'ipt.note.county': 'County shading (mean SOC)',
    'ipt.note.countyBody': 'The map background shades each county by the **arithmetic mean SOC of the sites in that county that actually have a SOC snapshot**: ≥80% green / 70-80% yellow / 60-70% orange / <60% red; a county with **fewer than 3 such sites is left grey** (one noisy site would swing the whole county). Offline sites and sites whose SOC was not reported are **excluded from the denominator** (they show "-" in the table and must not be counted as 0). The scope is the set of dots currently on the map, so the keyword filter changes the shading; "Watched only" filters the table only and leaves the shading untouched. County borders come from /gis/county-boundaries (the same GeoJSON as the GIS map and the person map, cached 1 hour server-side); three IPT organization spellings are normalized: Grand bassa → Grand Bassa, River cess → Rivercess, Bopolu → Gbarpolu (Bopolu is the capital of Gbarpolu county, not a county). Hover a county to see its mean SOC, how many sites feed the average and how many sites the county has; a county with no site in the current filter gets an outline only, no fill.',
    'ipt.kpi.alarms': 'Sites with alarms',
    'ipt.map.title': 'Site map (click a dot to drill down)',
