    'vmaxq.complaint.voiceHint': 'Judges the CSFB chain first (SGs → Extended Service Request → fallback) and VoLTE QCI=1; heavy-traffic KPIs down-weighted',
    'vmaxq.complaint.ottHint': 'Judges whether any STUN / long-lived session exists, then RTT jitter during the call; no app-layer signaling, network-side conclusions only',
