    'vmaxq.diag.overrideEdit': 'Edit override',
    'vmaxq.diag.overridden': 'Manually overridden',
    'vmaxq.diag.overriddenBy': 'Overridden by {{user}} at {{time}}',
    'vmaxq.diag.window': 'Window',
    'vmaxq.diag.sources': 'Source coverage',
    'vmaxq.diag.explain.availability': 'Service availability: scored from the procedure_status distribution of source 1100 (service-plane flow records) — Success adds, Timeout / Failure subtracts, and `S1-U Path Failure` gets a **separate hard penalty**: it usually still shows Success in procedure_status (Failure describes delivery, not success), so a status-only count would score a user-plane break as normal.',
    'vmaxq.diag.explain.latency': 'Response latency: main criterion = **P90** of `$first_resp_delay` in source 1300 (weight 0.7), secondary = mean `$tcp_resp_delay` (0.3). P90 rather than the mean, because the measured window showed 455ms average against a 118,765ms peak — the mean is flattened by small packets while users complain about the requests that stalled.',
    'vmaxq.diag.explain.transport': 'Transport quality: retransmission rate = (uplink + downlink retransmitted packets) ÷ (uplink + downlink total packets) × 100, same formula for out-of-order, both scored together. **When total packets are 0 no rate is computed** and only absolute counts are used — some upstream records carry KB under the same field name, so blind division would invent a rate.',
    'vmaxq.diag.explain.radio': 'Radio coverage: takes **P10** of RSRP from source 32 (radio-side samples), not the mean, combined with SINR / CQI. P10 because weak coverage is decided by "the worst few minutes": a user averaging -95dBm can still drop to -120 in one cell and fail to set up a call.',
    'vmaxq.diag.explain.common': 'These four scores are **computed in the frontend from the rules file** (`pages/vmaxDiagnosisRules.ts`); the API does not send scores. Their input is exactly the row sets listed under "Source coverage" below. 100 is the maximum, and a dash means the source a dimension needs returned no rows at all.',
    'vmaxq.diag.explain.sources': 'This row lists the **rows actually fetched per source** (frontend length of the API rows array). The backend pages over HTTP with per-source caps: 1300 = 1200 rows, 1100 = 800, 32 = 600, 1301 = 200. A trailing * on a tag means the API returned truncated=true, i.e. **rows were left unfetched** — in that case the four scores above describe a sample, not the whole window. Total rows fetched now: {n}.',
    'vmaxq.diag.explain.srcRows': '{src}: {n} rows fetched this time (length of the API rows array). The backend caps paging for this source; a trailing * on the tag means truncated=true, so **rows remain unfetched** and every statistic based on this source is a sample, not the full set.',
    'vmaxq.diag.sourceOk': '{{n}} records',
    'vmaxq.diag.sourceFail': 'Failed',
    'vmaxq.diag.sourceTimeout': 'Timeout',
    'vmaxq.diag.generatedAt': 'Generated {{time}}',
