    'vmaxq.override.revoke': 'Revoke override',
    'vmaxq.override.revokeConfirm': 'Revoking returns the page to the system verdict; the audit trail is kept. Revoke now?',
    'vmaxq.override.done': 'Override saved',
    'vmaxq.override.revoked': 'Override revoked',
    'vmaxq.override.note': 'The system verdict is never overwritten — both are kept on screen and in exports; the manual one is on top and marked "Manual"',
    /* ── Voice card (v2 §4.4) */
    'vmaxq.voice.card': 'Voice path',
    'vmaxq.voice.mode': 'Mode',
    'vmaxq.voice.mode.csfb': 'CSFB (fallback)',
    'vmaxq.voice.mode.volte': 'VoLTE (QCI=1 bearer)',
    'vmaxq.voice.mode.auto': 'Auto',
    'vmaxq.voice.mode.none': 'No voice activity detected',
    'vmaxq.voice.sgs': 'SGs location update',
    'vmaxq.explain.voiceCard': 'Every figure on this card is computed in the frontend by analyzeVoice over the **1100 (service-plane procedures) + 1300 (xDR)** row sets; the API does not send these counters. Mode: QCI=1 present in 1300 → VoLTE; else any of SGS / ESR / CSFB present → CSFB; nothing → no voice activity.',
    'vmaxq.explain.vSgs': '**Rows** in 1100 whose interface is SGS (SGs location update) — the first link of the CSFB evidence chain.',
    'vmaxq.explain.vTrig': 'Rows in 1100 whose request_cause contains CS FALLBACK TRIGGERED, i.e. the network really issued the fallback trigger.',
    'vmaxq.explain.vEsr': 'Rows in 1100 whose procedure_type contains EXTENDED SERVICE REQUEST (the terminal-side ESR). The success rate below is computed on exactly these.',
    'vmaxq.explain.vPage': 'Rows in 1100 whose procedure_type contains PAGING (terminating paging).',
    'vmaxq.explain.vBad': 'Rows in 1100 whose procedure_status is TIMEOUT or FAILURE, counted once per row. ⚠ Before 2026-11-05 a PAGING row that was TIMEOUT/FAILURE was added twice (once in the PAGING branch, once in the generic one); this is now fixed, so older screenshots show a larger number.',
    'vmaxq.explain.vQci1': 'Rows in 1300 (xDR) with qci equal to 1, i.e. VoLTE bearers. Deliberately not counted on qci=0 — measured qci=0 records are DNS packets.',
    'vmaxq.explain.vRate': '= successful ESR ÷ total ESR × 100 (computed on 1100; anything not TIMEOUT/FAILURE counts as success), 1 decimal. A dash means there was no ESR at all, not 0%.',
    'vmaxq.explain.vFallback': 'CSFB fallback time = the gap between each ESR and the **first** UE CONTEXT RELEASE after it, keeping only samples >0 and <30 s, averaged and rounded to whole milliseconds. A dash means no valid pair.',
    'vmaxq.explain.ottCard': 'This card is computed by analyzeOtt over the 1300 row set: rows are first judged as OTT calls by subservice / app_content_name / protocol, then grouped into sessions per app. The API does not send these values.',
    'vmaxq.explain.ottSessions': '= number of **OTT sessions grouped in the frontend** (length of the sessions array), not the number of xDR rows hit.',
    'vmaxq.explain.ottDuration': '= sum of session durations in seconds; the unit-bearing text is produced by durText (units differ per language).',
    'vmaxq.explain.ottRtt': '= arithmetic mean of dl_avg_rtt over the call sessions, rounded to whole ms. Turning red above 150 is only a **display** threshold in the rules file, not a business pass mark.',
    'vmaxq.explain.ottJitter': '= **standard deviation** (stdDev) of the same RTT sample set, not max minus min. The >60 red colouring is likewise display-only.',
    'vmaxq.explain.ottRetrans': '= (uplink + downlink retransmitted packets) ÷ (uplink + downlink total packets) × 100, 2 decimals; recorded as 0 when there are no packets instead of dividing by zero. **The denominator is only the rows fetched this time.**',
    'vmaxq.explain.ottBaseline': 'baseline = mean dl_avg_rtt of the **non-call** traffic records (the control group), rounded to whole ms. It tells you whether a high RTT is OTT itself or the whole path. Currently {v} ms.',
    'vmaxq.explain.gameFound': '⚠ This N is named sessions in the code but is actually the **sum of xDR rows** across hit apps (Σ records), not a session count. Matching has three tiers: subservice GAME/GAMING, app name containing a game keyword, or a name containing game/play that is not NETWORK STORAGE (the third tier is tagged "suspect" in the table).',
    'vmaxq.explain.gameRecords': '1300 rows matched for this app (records). The column header says "traffic" but this cell holds a **row count**.',
    'vmaxq.explain.gameRtt': '= mean of dl_avg_rtt per xDR row (falling back to ul_avg_rtt when missing), rounded to whole ms; a dash when no RTT is above 0.',
    'vmaxq.explain.gameJitter': '= standard deviation of that app\'s RTT sample (whole ms). With a single RTT value dispersion cannot be computed, so it shows a dash.',
    'vmaxq.explain.gameRetrans': '= (uplink + downlink retransmitted) ÷ (uplink + downlink total) × 100, 2 decimals; a dash when there are no packets.',
    'vmaxq.explain.rSamples': '= max(valid RSRP samples, valid SINR samples): readings equal to 0 are excluded. The small text below splits the rows per radio technology (2G/3G/4G/5G).',
    'vmaxq.explain.rRsrpAvg': '= arithmetic mean of all valid RSRP readings, rounded to whole dBm. The -110 / -100 colour bands are display thresholds only.',
    'vmaxq.explain.rRsrpP10': '= **P10 percentile** of RSRP (the boundary of the worst 10%), not the mean. Weak coverage is decided by the worst few minutes: a card averaging -95dBm can still drop to -120 and fail a call.',
    'vmaxq.explain.rSinrAvg': '= arithmetic mean of valid SINR readings, 1 decimal, in dB. A 0 means there was no valid reading.',
    'vmaxq.explain.rCqiAvg': '= arithmetic mean of valid CQI readings, 1 decimal. **Shows a dash when there is no CQI reading**, never a 0.',
    'vmaxq.explain.ccaCells': '= length of the camped-cell array returned by the CCA query (frontend takes .length). The table below pages 10 rows at a time; all pages add up to this number.',
    'vmaxq.explain.ccaCauses': '= length of the API result.causes array: one entry = one poor-quality indicator (KQI code + object + time), **not** a de-duplicated count of root-cause kinds.',
    'vmaxq.explain.flowTotal': '= API total_flux: traffic summed over the records **actually fetched** from XDR (formatted to KB by the backend). Upstream paging caps the row count, so this is the sum of that batch, not the user\'s full traffic in the window.',
    'vmaxq.explain.flowCatTraffic': '= traffic total for this category from the API (sum of its apps); the unit is decided by the backend _fmt_bytes_kb.',
    'vmaxq.explain.flowRatio': '= percentage string sent by the API: this app\'s traffic ÷ **its category** total × 100, 1 decimal; a dash when the category total is 0. Note the denominator is the category, not all traffic.',
    'vmaxq.voice.csfbTrigger': 'CS Fallback Triggered',
