    // ---- eFlow process graph: number hover explain (AGENTS.md 3.3c) ----
    'eflowFlow.explain.steps': 'Counts the **process nodes this ticket actually reached** (deduped, ordered canonically) — not the number of operations.\nAlarm Raised and TT Created are **marked unconditionally**, so any ticket starts at 2 steps.\nOnly the TT main flow counts; the WO field sub-flow is a separate lane and is excluded.\nThe denominator {{n}} = main-flow nodes only (WO lane excluded).',
    'eflowFlow.tip.steps': 'This ticket reached **{{reached}}** main-flow nodes out of {{total}}\nAlarm Raised and TT Created are marked unconditionally\nWO sub-flow counted separately: {{wo}} nodes (not in the number above)\nClick the card to clear the node selection',
    'eflowFlow.explain.rulesTotal': 'Denominator = **all rows of ocrule_details**: the backend query has no WHERE clause and no time filter, it is today\'s rule-table snapshot.\nIt is not "rules this ticket went through" and not "active rules".\n{{nodes}} of the {{total}} graph nodes carry at least one attached rule.',
    'eflowFlow.tip.rules': 'Rule table holds **{{rules}}** rows (whole table, unfiltered)\nThe "this ticket matched {{hits}}" figure = rules attached to the **current node** plus the create-stage severity rules, deduped\nMatched count is not a journey total — it moves with the current step',
    'eflowFlow.explain.nodeRulesTooltip': 'Attached = rules whose trigger step matches this node, deduped by (name, type, trigger step); active = status strictly equal to ACTIVE (case sensitive).',
    'eflowFlow.tip.nodeActive': '**{{active}}** rules on this node have status exactly ACTIVE\nThe rest of the {{total}} attached are either inactive or a case mismatch (Active / active do not count)',
    'eflowFlow.tip.nodeTotal': '**{{total}}** rules attached to this node\nDedupe key = (rule name, rule type, trigger step)\nOne rule can attach to several nodes and is counted on each — summing the nodes exceeds the {{rules}} table rows',
    'eflowFlow.explain.graph': 'The base graph is a rule-driven state machine: nodes are eFlow steps, edges derive from each rule\'s **trigger step** and **push path**.\nHighlighted nodes and edges are what this ticket actually walked.\n"active/total" on a node = rules attached to it; hover a node for its composition.',
    'eflowFlow.calcNote.title': 'How the eFlow graph is computed',
    'eflowFlow.calcNote.secGraph': 'Base graph and edges',
    'eflowFlow.calcNote.graph1': 'Rules come from the **whole ocrule_details table** (SELECT without WHERE); column names are probed against candidate lists for both SQL dialects, and if the rule_type column cannot be found the graph stays empty.',
    'eflowFlow.calcNote.graph2': 'Edges derive from triggerStep and the push-path text, normalised through _step_to_node (stripping GroupConfig_ / GroupDefault_ / CustomTitle_ prefixes). A rule whose step maps to no canonical node produces no edge.',
    'eflowFlow.calcNote.secAttach': 'How rules attach to a node',
    'eflowFlow.calcNote.attach1': 'A rule attaches to a node only when both hold: its triggerStep is in the node\'s declared step list, and its work-order type matches the node (nodes keyed wo_* take only eflow-wo, the rest only eflow-tt).',
    'eflowFlow.calcNote.attach2': 'When one rule matches several triggerStep variants it is deduped by (name, rule type, trigger step), so "N total" is the **deduped attachment count**.',
    'eflowFlow.calcNote.attach3': '"N active" requires status **strictly equal to ACTIVE** (surrounding spaces trimmed, case NOT folded). An upstream value of Active / active counts towards the total but not towards active.',
    'eflowFlow.calcNote.secReached': 'How the actual path is marked',
    'eflowFlow.calcNote.reached1': 'Alarm Raised and TT Created are marked unconditionally; when a WO exists, either FO Accept or FO Process is reserved.',
    'eflowFlow.calcNote.reached2': 'Other nodes come from the detail fields fo_accept_detail, fo_process_detail and confirm_detail — timestamps and handler names are scraped out of that free text with a regular expression, so a format change silently loses the mark.',
    'eflowFlow.calcNote.reached3': 'The current node reads operation_type and falls back to status; Closed is marked only with actual_completion_time or a Closed status. Each node counts once.',
    'eflowFlow.calcNote.secCaveat': 'Reading the graph',
    'eflowFlow.calcNote.caveat1': 'The rule table is a **current snapshot** with no time filter — a ticket that has been in flow for months is drawn against today\'s rules, which may not be the ones that actually routed it.',
    'eflowFlow.calcNote.caveat2': '"Matched this ticket" covers only the rules attached to the **current node** plus the create-stage severity rules (deduped by name+node); it is not the total set of rules the ticket met.',
    'eflowFlow.kpi.wo': 'Field WO',
