    'qa.ume.history': 'History alarms (same site)',
    'qa.ume.historyCell': 'History alarms (same cell)',
    'qa.ume.noHistory': 'No history alarm in the last {days} days',
    'qa.ume.totalRows': 'matched',
    'qa.explain.umeHistoryTotal': 'The N in "N matched" = API history.total, i.e. totalcount returned by UME (all rows under the same query). The lookup uses **the same site ± 2 minutes around this alarm\'s raise time** and returns at most 30 rows per call, so UME\'s total is often larger than the table. A dash means it could not be fetched — never a fake 0.',
    'qa.explain.umeHistoryShown': 'The {n} in brackets = rows actually fetched and rendered (API history.count), capped at 30 per call. The gap is not lost data; UME only returns the first 30.',
    'qa.explain.ruleCount': 'N = ACTIVE rules counted by the backend after reading eflow_TT_rules.xlsx (API rules.count). The two timestamps next to it are the table\'s update time and this collection time — when a verdict disagrees with the manual, check those timestamps first.',
    'qa.explain.pushRuleHit': 'N = how many push rules matched this ticket (frontend length of the array the API returned, no further filtering). With zero matches the UI shows "none" rather than 0.',
    'qa.explain.cells': 'The {n} in brackets = total same-site cells returned by the API (frontend array length). The tags below render **at most 60**, so extra cells are off-screen.',
    'qa.explain.docCount': '{n} = entries the documentation tree scan returned (frontend array length); the path after it is the current scan root.',
    'qa.explain.sectionCount': 'The {n} in brackets = fields in the "{sec}" section (length of API report.fields[].items). Expand the header to check them one by one.',
    'qa.explain.searchHits': '{n} = **documents** hit by this full-text search (frontend length of the hit array) — not keyword occurrences, not rows.',
    'qa.explain.elapsed': '{v} seconds = API elapsed_total_sec (falling back to elapsed_sec): backend time across "read DB + rule matching + building the response", **excluding** browser rendering and network round-trip.',
    'qa.explain.bInput': 'Valid tickets {valid} = API input.valid: after splitting the pasted text, dropping blanks and duplicates, this many remain eligible for the check. Other API figures are not shown here — {total} raw, {invalid} invalid, {dup} duplicated (lengths of input.invalid / input.duplicated). If input.truncated is set, the input exceeded the endpoint limit and the excess was not evaluated.',
    'qa.explain.bFound': '= API summary.found: tickets that have a record in eflow_tt.',
    'qa.explain.bMiss': '= summary.not_found: tickets with no record. They are listed under "not found", not in the table below.',
    'qa.explain.bOk': '= summary.level_ok: rows whose current severity already matches the rule table.',
    'qa.explain.bAdjust': '= summary.level_adjust: rows needing a severity change; tick "only need adjustment" to isolate them.',
    'qa.explain.bUnknown': '= summary.level_unknown: rows whose severity cannot be decided (missing key field, or a value outside the enum).',
    'qa.explain.bTableCount': 'n = rows rendered under the current filter; total = length of the API rows array (**tickets with a record only**; unmatched tickets are counted separately in not_found). The six summary chips above always describe the whole input and do not follow this tick.',
