    'cr.kpi.completionRateHint': 'Executed {{executed}} / Planned {{planned}}',
    // ---- CR change analysis: KPI and rate cards, number hover explain (AGENTS.md 3.3c) ----
    'cr.explain.cards': 'All eight buckets are decided by the backend (table eflow_cr, time column request_registration_time):\nplanned = planned_start_time not null; executed = actual_start_time not null; on time = executed **and** actual_start_time <= planned_start_time; unexecuted = planned with an empty actual; closed / canceled / open = status after normalisation compared exactly or NOT IN.\n⚠ "on time" is a **lexicographic text comparison**, which relies on upstream timestamps being formatted consistently (the code comment admits this assumption).',
    'cr.tip.sumOverCats': 'This figure = the API summary: the backend narrows to the **{{n}} selected categories inside the same SQL** (a parameterised IN, never string interpolation).\nThe page no longer adds the per-category counts itself, so the overview, the three rates, the category table, the status mix, the monthly and sub-category blocks all come from one and the same set; nothing selected means the whole window.',
    'cr.tip.total': 'Total = the number of CR rows in the window (one CR per row).',
    'cr.tip.planned': 'Planned = rows whose planned_start_time is **not null**.',
    'cr.tip.executed': 'Executed = rows whose actual_start_time is **not null**.\n⚠ It is not a subset of Planned: a row with an actual but no planned counts here and not in Planned, so **Planned ≠ Executed + Unexecuted**.',
    'cr.tip.unexecuted': 'Unexecuted = planned rows whose actual_start_time is empty.',
    'cr.tip.onTime': 'On time = executed rows with actual_start_time ≤ planned_start_time (lexicographic text comparison).',
    'cr.tip.delayed': 'Delayed = executed rows that did not finish on time.',
    'cr.tip.closed': 'Closed = rows whose normalised status (trimmed, lower-cased) equals closed.',
    'cr.tip.open': 'Open = rows whose normalised status is **not** in the closed / canceled word list — a status name invented upstream falls in here by default.',
    'cr.tip.rateCompletion': 'Completion rate = executed {{executed}} ÷ planned {{planned}} (computed by the backend). The denominator is **planned**, not the total.',
    'cr.tip.rateOnTime': 'On-time rate = on time {{onTime}} ÷ executed {{executed}} (computed by the backend). The denominator is **executed**, not the total.',
    'cr.tip.rateClosure': 'Closure rate = closed {{closed}} ÷ total {{total}}. The denominator is the **total**.',
    'cr.tip.rateFrontend': 'The three rates use **three different denominators**, so comparing the percentages side by side is meaningless.\nThey are computed once by the backend _rate and sent down (a zero denominator yields null and the UI shows —, never 0%); only the 80 / 50 colour thresholds live in the frontend (crTypes.ts, commented as a business convention).',
    'cr.kpi.onTimeRate': 'On-Time Execution Rate',
    'cr.kpi.onTimeRateHint': 'On time {{onTime}} / Executed {{executed}}',
    'cr.kpi.closureRate': 'Closure Rate',
    'cr.kpi.closureRateHint': 'Closed {{closed}} / Total {{total}}',
