    'pm.explain.closed': 'Closed = `UPPER(TRIM(status)) = \'CLOSED\'`. The dynamically created eflow_pm table holds both cases of the column, hence normalise-then-compare.',
    'pm.explain.open': 'Open = the normalised status is **not** CLOSED — a status name invented upstream falls in here by default.',
    'pm.explain.overdue': 'Overdue = `UPPER(TRIM(pmt_overdue)) = \'YES\'` — the source table\'s own verdict is taken **as-is; this page never recomputes it from planned/actual dates**. That matters: if the column is left blank upstream this stays 0 even when orders really are late.',
    'pm.explain.onTime': 'Not overdue = the normalised pmt_overdue is not YES. It complements "overdue" over the same denominator (total orders).',
    'pm.explain.notStarted': 'Not started = the order has **zero completed items** (completed_items accumulates completed detail lines).',
    'pm.explain.closedOverdue': 'Closed but overdue = both status=CLOSED and pmt_overdue=YES hold.',
    'pm.explain.openOverdue': 'Open and overdue = both status≠CLOSED and pmt_overdue=YES hold — this is the batch worth chasing right now.',
    'pm.explain.rateClosure': 'Closure rate = closed ÷ total.',
    'pm.explain.rateOverdue': 'Overdue rate = overdue ÷ total. **Lower is better**, so the colour scale is inverted (high = red).',
    'pm.explain.rateStart': 'Started rate = (total − not started) ÷ total, i.e. the share of orders with at least one item completed.',
    'pm.tip.count': 'This figure = the matching field of the API summary = **{v}** (counted by a single backend SQL with SUM(CASE WHEN …))\nIts share of {total} is left for you to read — the API sends no percentage field\nClick the card to drill down; the detail row count equals this number exactly',
    'pm.tip.countTotal': 'This figure = the total field of the API summary = **{v}**: work-order rows of this source inside the time window, counted by one backend COUNT(*)\nIt is also the denominator of the closure and overdue rates below\nClicking the card drills into **all** work orders; the detail row count equals this number exactly',
    'pm.tip.rate': '{rate}\nThe denominator is shown in the small line below; rates come from the backend `_rate` (a zero denominator returns null → shown as —, never 0%)',

