    'noc.explainCard.total': 'Sum of each person\'s ticket count. One TT row counts once, attributed to **last_processer** (not current_handler).\nRows fall into the month by alarm_occur_time, the same field the alarm dashboard uses.',
    'noc.tip.total': '**{{v}}** tickets in total, spread over {{people}} people\nPer-person load moves with the search box and the owner filter',
    'noc.explainCard.avgMismatch': '⚠ This is the **arithmetic mean of each person\'s mismatch rate (one vote per person)**, not Σmismatch ÷ Σtickets.\nA person\'s rate = mismatched tickets ÷ **tickets with a filed root cause** (not all their tickets); people who filed none are excluded from the mean.\nThe code intends to exempt Auto-recovery / Uknown / Force Majeure / Planned work, but the exemption tuple is mixed case while the filed value is upper-cased, so **it never matches** — those tickets still count as mismatches today (implementation defect, registered for a business decision, not changed silently).',
    'noc.tip.avgMismatch': 'Equal-weight mean of the per-person rates = **{{v}}%**\nRed threshold ≥30% (same as the red flag)',
    'noc.explainCard.avgDur': 'Arithmetic mean (**one vote per person**) of the per-person average handling time, in hours.\nEach duration is scraped from the create / fo_accept / fo_process / confirm detail text by regular expression; **anything over 7 days is dropped as a false reading**, and rows without parsable details are excluded from the average.',
    'noc.tip.avgDur': 'Equal-weight mean of the per-person durations = **{{v}} hours**\nRed threshold ≥12h (same as the red flag)',
    'noc.explainCard.slaPass': 'Different from the two cards above: this is the **pooled ratio** ΣPass ÷ Σ(Pass+Failed), weighted by ticket volume, not the mean of individual pass rates.\nSo it can sit clearly above or below the "per-person mean" — high-volume operators dominate it.\nThe denominator accepts only sla_status Pass / Failed; other statuses and blanks are excluded.',
    'noc.tip.slaPass': 'Pooled pass rate = **{{v}}%**\nGreen threshold ≥90%, otherwise amber\nThe denominator holds Pass and Failed only — tickets with no SLA verdict are not in it',
    'noc.explainCard.redFlag': 'Number of people **flagged red**: one flag per person no matter how many conditions they hit.\nThree thresholds: mismatch rate ≥30%, average handling ≥12 hours, SLA fail rate ≥50%.\nWhich conditions each person hit is listed in the alert below; those reason strings are built by the backend and are currently Chinese only.',
    'noc.tip.redFlag': '**{{n}}** people flagged this month\nCriteria: mismatch ≥30% or average handling ≥12h or SLA fail ≥50%\nA person hitting several still counts once',
    'noc.tip.noSample': 'No sample to average this month: every person has a null value for this metric (nobody filed a root cause / no duration parsed).\nShown as — rather than 0, because 0 would read as "everyone is fine".',
    'noc.tip.slaNoTotal': 'No ticket carried a Pass / Failed SLA status this month, so the denominator is 0 and no rate can be computed.\nShown as — rather than 0%.',
    'noc.tip.rankCard': '{{who}}: {{total}} tickets this month, **{{rc}}** with a filed root cause, **{{mis}}** judged mismatched\nThe mismatch rate divides by {{rc}} (tickets with a root cause), not by {{total}}\nSLA: Pass {{pass}} out of {{slaTotal}} counted (Pass and Failed only)\nClick the card to drill into this person\'s mismatched tickets',
    'noc.cardHint': 'Click to drill down',
