    'fme.explain.topAvail': 'Arithmetic mean of site availability for every site under this RAT this month, sorted descending. Click a card to see that FME\'s sites and WOs.',
    'fme.explain.bottomAvail': 'The three FMEs with the lowest availability — the priority follow-up targets this month.',
    'fme.explain.topWo': 'The three FMEs with the most WOs created inside the selected month.\n⚠ The rank badge is the **raw `wo_rank` from the backend**, which is ranked **ascending** by WO count (#1 = fewest WOs) — so these three cards show late ranks such as #41 / #42 / #43, not 1/2/3. The badge comes from the same field as the "WO rank" column in the table below; do not read it as "number one".',
    'fme.explain.bottomWo': 'The three FMEs with the fewest WOs — their badges are #1 / #2 / #3 (the backend ranks ascending by WO count, so the fewest is #1).',
    'fme.chartHint': 'Click a bar/line to drill into that FME',
    // ---- SLA achievement ----
    'fme.slaRate': 'SLA achievement',
    'fme.axis.sla': 'SLA achievement(%)',
    'fme.col.slaRate': 'SLA Achievement',
    'fme.col.slaPass': 'SLA Passed/Total',
    'fme.col.slaFail': 'SLA Failed',
    'fme.col.slaRank': 'SLA Rank',
    'fme.stat.sla': 'SLA Achievement',
    'fme.stat.slaDetail': 'Passed {pass} / counted {total}',
    'fme.stat.slaFail': 'SLA Failed WO',
    'fme.topSla': 'Top 3 by SLA achievement',
    'fme.topSlaSub': 'Highest on-time WO completion this month',
    'fme.bottomSla': 'Bottom 3 by SLA achievement',
    'fme.bottomSlaSub': 'Most overdue WOs — needs attention',
    'fme.slaRankSmallSample': 'Fewer than 5 samples — excluded from SLA ranking',
    // ---- Number hover explanations (2026-11-05, AGENTS.md 3.3c); calibers verified in services/fme_data/fme_ranking_service.py ----
    'fme.tip.fmeCount': 'Number of FMEs on the board for the selected month (API `summary.fme_count`; the page does not recompute it).\nA dash means the field was not returned — **not "zero people"**; a literal 0 usually means no work orders in that month could be attributed to a site on the board.',
    'fme.tip.siteCount': 'Sites covered by the board (API `summary.site_count`). One row = one site, so it equals the number of rows in the table below;\nsites whose availability is empty **stay on the board** (they just do not take part in the availability ranking).',
    'fme.tip.woTotal': 'Total WOs = orders **created inside the selected calendar month** that can be attributed to a site on the board:\nthe window is "first of month ≤ t < first of next month" (left-closed, right-open, `month_bounds_exclusive`), and the time column is detected\nfrom the table schema by `detect_wo_schema()` (if it is missing the whole block comes back empty with a warning).\nAttribution prefers `site_id`; rows without one fall back to a **normalised site name** (whitespace collapsed, trimmed, lower-cased — `norm_name`).\nSo changing the month moves these numbers as a batch — they are not cumulative.',
    'fme.tip.woOpen': 'Open count = the orders in that same batch whose status is not treated as closed. The colour only says "any vs none", not good vs bad.\n⚠ The whole platform has three definitions of "open" (this page tests the row status field, the spare-parts report de-duplicates by document number with a word list, the warehouse board compares exactly), so the three figures are not meant to reconcile.',
    'fme.tip.slaRate': 'Achievement rate = (Pass + Within SLA) ÷ (Pass + Failed).\n⚠ **The denominator is not every order of the month**: records whose `sla_status` is empty or another value are excluded from both sides\n(`fme_ranking_service.py:118-122`), deliberately so that unknown statuses cannot drag the rate down — the y in the `x/y` below is the real denominator.\nWhen there is nothing to compute the API returns null and the page shows — (never 0%); `sla_rank` is also withheld (see the column header ⓘ).',
    'fme.tip.slaFail': 'Number of Failed records (same source as that denominator); every ratio is computed by the backend and the page only applies the ×100 display conversion.',
    'fme.tip.rank.avail': 'The first column = `availability_rank`, assigned by the backend: availability **descending** (#1 = best).\nTies are broken in two steps — first the higher SLA rate, then the FME name (`fme_ranking_service.py:255-260`); rows without availability data do not get a rank.\n⚠ The three board card sets used to sort by value on their own, which disagreed with these columns in direction and tie-breaks (since 2026-11-05 the card badges use the backend rank and the frontend no longer sorts).',
    'fme.tip.rank.wo': '`wo_rank` is assigned by the backend: **ascending by WO count, #1 = fewest WOs** (ties broken by FME name).\nThat is why the "Top 3 by WO count" cards show late ranks such as #41/#42/#43 rather than 1/2/3 — the cards and this column share one source, and the frontend no longer re-sorts.\n( corrected 2026-11-05: the cards used to rank descending by WO count, the opposite of this column, so the page showed two different "number ones".)',
    'fme.tip.rank.sla': '`sla_rank` is assigned by the backend: achievement rate **descending** (#1 = best), and **FMEs with fewer than 5 samples in the denominator get no rank**\n(`sla_rank` is null and the page shows —), otherwise "2 orders both passed" would outrank "80 orders all passed".\nThe availability ranking lives in `availability_rank` (first column) and has its own tie-break on SLA.',
    'fme.explain.topSla': 'SLA achievement = WOs with sla_status Pass/Within SLA ÷ (Pass + Failed). FMEs with fewer than 5 samples are excluded from ranking so small samples cannot inflate the result.',
    'fme.explain.bottomSla': 'The three FMEs with the lowest SLA achievement — the priority targets for fixing overdue work orders this month.',
