    // ---- SP details report: number hover explain (AGENTS.md 3.3c) ----
    // Calibers re-read from get_summary() / _sheet_stats() in backend/services/sp_details_service.py.
    // ⚠ This page reads the *_source.xlsx snapshots taken **before any filtering**, while sp_report / com_report
    //   read the filtered consolidated workbook — same-named metrics are systematically larger here by design.
    'spDet.explain.records': 'Records = the **sum of data rows across sheets** (backend Σ len(rows)), no de-duplication across sheets — a material appearing in both inbound and outbound counts twice.',
    'spDet.tip.records': '{n} rows added up from {sheets} sheets\nWhen a sheet\'s *_source.xlsx raw snapshot is missing it falls back to the filtered detail, so that sheet reads smaller (the banner at the top names which)',
    'spDet.explain.stockQty': 'Stock = the Stock Qty column of the Inventory sheet, **summed row by row** to 2 decimals.',
    'spDet.explain.inboundQty': 'Inbound = the Qty column of the Inbound sheet, summed row by row.',
    'spDet.explain.outboundQty': 'Outbound = the Qty column of the Outbound sheet, summed row by row.',
    'spDet.explain.transferQty': 'Transfer = the Qty column of the Transfer sheet, summed row by row (Transfer Return, when present, stays its own sheet and is not folded into this figure).',
    'spDet.tip.bySheetQty': 'This value = the {col} column of the {sheet} sheet summed = {v}\nIt is not derived from another sheet and not recomputed as a difference by this page',
    'spDet.explain.warehouses': 'Warehouses = the number of **distinct values in the union** of the warehouse columns.\n⚠ The transfer sheet contributes both "original" and "target" warehouse names, so one transfer adds two names — this figure is deliberately larger than the number of storage locations.',
    'spDet.tip.warehouses': '**{n}** warehouse names after union de-duplication\nEquality is on the raw text (case and surrounding spaces are not normalised), so the same site written two ways counts twice',
    'spDet.explain.materials': 'Materials = distinct Material No. values across **all** sheets. ⚠ This is a true de-duplicated count, unlike the card of the same name on the spareparts report, which counts **rows**.',
    'spDet.tip.materials': '**{n}** material numbers de-duplicated across every sheet\nA material present in several sheets still counts once',
    'spDet.explain.openTickets': 'Open tickets = the **sum** of each sheet\'s open_count.\nWith a document-number column it counts distinct document numbers; sheets without one degrade to counting rows; the closed test is **"closed" not in status.lower()**.\n⚠ The whole site has three different definitions of "open" (this page: per-row substring match / spareparts report: distinct document number + full word list / warehouse board: exact == "closed"), so one business fact shows three numbers. Known caliber split, left for a decision.',
    'spDet.tip.openTickets': 'Summed over sheets = **{n}** (rows)\nThis page counts with the **sp_details** rule and must not be reconciled against the spareparts report or the warehouse board',
