    // ---- SP / consumables report: overview cards and per-sheet cards, number hover explain (AGENTS.md 3.3c) ----
    'spRep.explain.materials': 'Materials = the **number of data rows** in Summary-Current (backend len(rows)), **not** a de-duplicated count of material numbers.',
    'spRep.tip.materials': '{n} rows in this sheet (one material occupies one row, so rows equal items today; the two diverge if the generator changes the layout)',
    'spRep.explain.inbound': 'Inbound = the raw value of the Inbound Qty cell in the **Total row** of Summary-Current. The page neither re-sums nor converts it.',
    'spRep.explain.outbound': 'Outbound = the raw Outbound Qty value in the Total row.',
    'spRep.explain.inventory': 'Inventory = the raw Inventory Qty value in the Total row.',
    'spRep.explain.difference': 'Difference = the raw Difference value in the Total row (the generator\'s stock-minus-consumption figure). **Negative turns red** — a colouring rule of this page, not a backend verdict.',
    'spRep.explain.safetyStock': 'Safety stock = the raw Safety Stock value in the Total row.',
    'spRep.explain.replenishment': 'Replenishment = the raw Replenishment Qty value in the Total row.',
    'spRep.explain.urgent': 'Urgent = the **number of rows** whose Alert Level is exactly "Urgent Replenish".\n⚠ Different unit from its neighbours: this one counts **material lines**, while Inbound / Outbound count **quantity (Qty)** — do not subtract one from the other.',
    'spRep.tip.urgent': '{n} material lines flagged Urgent Replenish\nThe test is the literal value the Excel generator wrote into Alert Level; this page only matches it exactly\nAbove 0 the card is outlined and turns red',
    'spRep.tip.fromTotalRow': 'This value = the raw **Total row · {col} cell** of the consolidated workbook: {v}\nWhen the column is missing or not numeric the backend returns **0.0** — so a "0" can be a real zero or an absent/empty column; check the workbook\nSource file: {file}',
    'spRep.tip.sheetRecords': '{sheet}: {n} data rows read (backend len(rows))\nClick this card to switch to that sheet; the filtered row count shows in the toolbar',
    'spRep.tip.sheetQty': 'Sheet quantity = the {col} column summed row by row, 2 decimals = {v}\nThe quantity column is decided per sheet (Summary-Current uses Inventory Qty, the movement sheets use their own Qty column), not chosen by this page',
    'spRep.tip.openCountDb': '{n} open documents — this figure comes from the **live database** (same caliber as the SPMS number on the MsPortal QC panel: distinct document number + status word list).\nReason: the workbook is a 05:55 snapshot while the DB lands at 07:00, so within one day the DB is fresher; if the two disagreed users would assume one is wrong, so the spareparts page follows the DB.\nAll other statistics (records, quantity totals, warehouses, Domain mix) stay on the Excel snapshot so the page matches the emailed attachment line for line.',
    'spRep.tip.openCountExcel': '{n} open documents — this figure comes from the **Excel snapshot** (distinct document number + status word list), not the live database.\nThe live override applies to spareparts only; consumables tables are landed by a different sync job and we do not guess their names, so the workbook caliber is kept (fixed 2026-11-04 — previously consumables were wrongly overridden with spareparts numbers).',
    'spRep.tip.filteredQty': 'Left of the slash = {col} summed over the **rows matching the current filters**; right of the slash = the whole sheet total.\nThe two come from different endpoints (detail query vs summary), so they legitimately differ while a filter is active.',
    'spRep.tip.filteredRows': 'Left = rows matching the current filters and search; right = total rows in this sheet.\nIf only the left number shrinks, that is the filter working, not data disappearing.',
