    'msKpi.matrixHint': 'Click a header or a cell for that KPI daily trend. The Month row is the workbook summary row; achievement columns are coloured by target (green = met, red = below). On daily rows only the below-target values are highlighted.',
    'msKpi.docTitle': 'Report definitions (identical to the Excel)',
    'msKpi.doc.metRule': 'Target check: month value vs target by direction — KPIs whose name contains NUR / DCR / Blocking / Congestion / Unavailability are lower-is-better, all others higher-is-better.',
    'msKpi.doc.woScope': 'WO SLA scope: five groups — TTR plus TTR_P1_4h / P2_8h / P3_16h / P4_2Days — each with Total / Within SLA / Achieve. P1_4h has no data in this workbook.',
    'msKpi.doc.persite': 'PerSite KPI values are the share of sites meeting their threshold, all targeting 90% (the sheet group names are 2G (90%) / 3G (90%)), matching the generator conditional formatting.',
