    // ---- SP material summary: number hover explain (AGENTS.md 3.3c) ----
    'spMat.explainCol.anchor': 'The opening group = the two-way split of each group\'s stock on the **anchor snapshot day** (anchor_date).\nBucketing: rows whose status is damage go to "needs repair"; otherwise a material type containing "spare" goes to spare-good and one containing "consum" to consumables.\nStock comes from SUM(Stock Qty) of inventory_details for that snapshot date; a row joins a group when its Warehouse Id matches exactly or by prefix **or** its Warehouse Name contains a group keyword (each group also carries exclusion words, e.g. 1st WH excludes names containing "2nd floor"); only rows matching nothing land in Others.',
    'spMat.explainCol.current': 'The current group = the same groups and buckets on the **current snapshot day** (current_date).\n"Consumption" = some opening snapshot − this column, so this group is the subtrahend of all three consumption windows.',
    'spMat.tip.anchor': '{label}: stock on the opening snapshot = **{v}**\nGrouping: an exact/prefix Warehouse Id **or** a Warehouse Name containing a group keyword (each group also has exclusion words); only a total miss falls into Others',
    'spMat.tip.current': '{label}: stock on the current snapshot = **{v}**\nAll three consumption windows subtract this',
    'spMat.tip.needRepair': '{label}: stock bucketed as damage = **{v}**\nThis is "needs repair" and is **not part of** the spare-good + consumables totals in the opening/current groups',
    'spMat.tip.repairOutbound': '{label}: repair outbound = **{v}**\n⚠ This column comes from **another table** (outband_details where Outbound Type = Repair Outbound; one row = one serial number with Qty always 1) and that table has only a warehouse name, no Warehouse Id, so grouping is by name alone. Its window also differs from the stock snapshots — do not subtract it from the stock columns',
    'spMat.tip.consumption': '{label}: consumption in this window = **opening stock − current stock** = {v}\nOpening total {aTotal}, current total {cTotal} (the totals cover spare-good + consumables only, **excluding damage**)\nThe spare / consumables split columns add up to this whole column',
    'spMat.tip.negative': '⚠ This is **negative**: stock rose over the period because of inbound or transfer back-fill. The consumption measure is only "opening − current" and **does not credit replenishment**, so negatives are legitimate — the backend also raises a warning naming them.',
    'spMat.tip.unitIsRows': 'Unit reminder: these are SUM(Stock Qty) quantities, not counts of distinct materials',
    'spMat.tip.drill': 'Click a number to drill into the per-material rows for that group and column',
    'spMat.tip.modalTotal': 'Total = the quantity column summed over the **{n} rows currently matching the search box** (the API does not send this total; it is an immediate frontend aggregation).\nThe drill-down returned {all} rows in total; clear the search box and the two agree.',
    'spMat.warnTitle': 'Data notes',
    'spMat.staleBackend': 'The backend service is still an older build (it does not return the Repair Outbound / consumption split fields), so those columns show 0. Please run fix_backend.bat on the server to restart the backend, then refresh.',
    'spMat.docTitle': 'Calculation basis',
    'spMat.doc1': 'Spare Part (Good) = total stock qty of spare parts whose Material Status is not damage; Consumables = total stock qty of consumables.',
    'spMat.doc2': 'Current Date is the latest snapshot date in the inventory table; the baseline date defaults to the 1st day of that snapshot month and can be changed.',
    'spMat.doc3': 'Total Consumption = opening stock − current stock, split by Spare Part and Consumables; the three windows are the baseline date, the 1st of the month, and Monday of the week. A negative value means inbound replenishment / transfer-in during the period.',
    'spMat.doc4': 'Need Repair = qty with Material Status = damage in the current snapshot; Repair Outbound = outbound qty of type "Repair Outbound" from the 1st of this month 00:00:00 to now, grouped by warehouse.',
    'spMat.doc5': 'Click any number to drill down: stock columns show that day\'s material rows, consumption columns show an opening-vs-closing comparison by material, Repair Outbound shows this month\'s repair outbound records.',
    'siteAvail.month': 'Month',
