    'siteAvail.monthAvgTip': 'Monthly average of {v} site-level availability: the arithmetic mean over the days **with data** (missing days skipped, not zero-filled).\nNote it is **one vote per site**, not weighted by traffic or cell count.',
    'siteAvail.withData': '{v} sites with data',
