    'siteAvail.daysBelowTip': 'Days whose daily value < threshold {v}%; the denominator is the days **with data**, not all days of the month.\nThe threshold comes from the page input and recomputes immediately without a new query.',
    'siteAvail.dayUnit': 'd',
    'siteAvail.ticketsCol': 'TTs',
    'siteAvail.totalSites': '{v} sites in total',
    'siteAvail.noDailyData': 'No daily availability data ({v}) for this site this month',
    'siteAvail.weekTip': '{label} ({range}, weeks start Monday, edge weeks clipped to the month)\n= arithmetic mean of the days with data inside that week; a dash means no data was synced.',
    'siteAvail.explain.sites': 'Before the slash = the number of site rows **after the current search filter**; after the slash = all sites in scope for the month (does not change with search).\nSo the first number shrinks when you search - that is filtering, not missing data.',
    'siteAvail.explain.monthAvg': 'Monthly average for the selected technology = the arithmetic mean of each filtered site monthly value (**one vote per site**, not weighted by traffic or cell count).\n⚠️ It only covers the sites visible after the search filter, a different population from the backend network-wide summary - clear the search box for the whole-network value.',
    'siteAvail.explain.withData': 'Sites among the filtered ones that have **at least one day with data** this month for that technology. Missing days are skipped, never filled with 0.',
    'siteAvail.explain.below': 'Filtered sites whose **monthly average** is below the threshold. The threshold comes from the page input (default 99.65%) and recomputes immediately without a new query.',
    'siteAvail.explain.monthTickets': 'Tickets (TT) this month = rows of eflow_tt whose **created_time** falls in the month; the orange "open" figure is status not Closed.\nEach TT is assigned to exactly one site - site_id matched first, then the normalized site name - so no ticket is counted twice.',
    'siteAvail.explain.generatedAt': 'When the backend produced this snapshot. The machine clock is **UTC**, not local time; look at the day columns for how current the data itself is.',
    'siteAvail.tip.monthAvg': 'Arithmetic mean over the days **with data** this month (missing days skipped, not zero-filled)\n{d} days with data, {b} of them below the threshold\nLowest {min}; one vote per site, not comparable with the cell-level measure',
    'siteAvail.tip.min': 'Lowest daily value {min}\nOn {day}',
    'siteAvail.tip.daysBelow': '{n} / {d} days below the {thr}% threshold\nThe denominator is days with data, not all days of the month',
    'siteAvail.tip.day': 'Site-level daily value for {day} (raw UME reading; TDD derived from service time)\nA dash means no data was synced that day, not 0% availability',
    'siteAvail.tip.ticketCell': 'TT of this site this month: {t} total, {o} open, {c} closed\nAssigned by created_time falling in the month',
