    'availMs.colMttr': 'MTTR (min)',
    'availSum.explainCol': 'Availability = **SUM(numerator) / SUM(denominator)**, not a plain average across sites.\nSource: the derived table availability_daily (rebuilt every day at 06:10 by the avail_recon_sync job from the remote site daily KPIs).\nHover a number to see the numerator and denominator of that cell.',
    'availSum.explainKpi': 'Network-wide availability for this technology = the ALL-region cell of the main table: all (site x day) observations of the period summed and divided, i.e. weighted by site-days.\nIt is **not** the mean of the regions, and it **includes** sites that do not match the site master data.\nClick the card to drill into that technology.',
    'availSum.explainUnmatched': 'Unmatched share = the fraction of the **denominator (site-day observations)** contributed by sites whose names do not match the site master data (empty FME_Region) — measured around 2.3%.\nThose sites **are included in the ALL region**, so the ALL row ≠ the regions added up. That is the measure itself, not missing data.',
    'availSum.explainRegionKpi': 'Region availability = SUM(numerator)/SUM(denominator) over **all technologies and all site types** of that region in the period (weighted by site-days), not a mean of the per-technology figures.\nThe regions listed here **follow the site master data master_site_db** (currently North / South; the page follows the data automatically, nothing is hard-coded); sites that do not match the master data are **in no region card** (they form a separate "Unmatched" row and are counted in the ALL row of avail_ms).\nClick the card to drill into that region.',
    'availSum.tip.ratio': 'Numerator {{n}} / denominator {{d}}',
    'availSum.tip.parts': 'Denominator = site-day observations in the period (one per site per day with data); numerator = the availabilities of those observations summed (0-1 per site-day)',
    'availSum.tip.weighted': 'So this cell is a **site-day weighted** mean: slices with more sites and more days carry more weight',
    'availSum.tip.delta': 'Change {{delta}}pp vs the previous period (positive = better, same measure)',
    'availSum.tip.drill': 'Click the number to drill into detail',
