    /* ---- County-level availability (AvailCounty.tsx, page=avail_county) ----
     * See backend/services/avail_county_service.py: rows = county
     * (eflow_site.province_county), columns = 2G/3G/4G, day/week on tabs.
     * ⚠️ The measure differs from avail_ms / avail_flm (site-weighted average
     *    here, SUM(numerator)/SUM(denominator) there) — hence the explicit note. */
    'availCounty.tabDay': 'Daily',
    'availCounty.tabWeek': 'Weekly',
    'availCounty.tech2G': '2G availability',
    'availCounty.tech3G': '3G availability',
    'availCounty.tech4G': '4G availability',
    'availCounty.allNetwork': 'Whole network',
    'availCounty.unmatched': 'Unmatched sites',
    'availCounty.unmatchedTag': 'Includes unmatched sites',
    'availCounty.note.unmatchedTitle': 'About the "Unmatched sites" row',
    'availCounty.unmatchedWhy': 'The "Unmatched sites" row sums up sites that **cannot be matched to the site master data on the PG side**. They do have availability figures, but belong to no county — so they are **not counted into any county** and are not part of the county average shown as whole-network.',
    'availCounty.caliberTitle': 'About this measure',
    'availCounty.caliberNote': 'Site-level availability comes from the UME MS SLA site-level daily tables (2G=TCH in service rate, 3G=Cell Validity Rate, 4G=[FDD]Cell Availability); sites are matched to the master data by **name** (site_id does not line up) and the county is eflow_site.province_county. This page uses a **site-weighted average**, which differs from the SUM(numerator)/SUM(denominator) measure of the Availability Matrix and FLM Availability pages — the figures of the two are not expected to match.',
    'availCounty.metric2G': 'TCH in service rate(%)',
    'availCounty.metric3G': 'Cell Validity Rate(%)',
    'availCounty.metric4G': '[FDD]Cell Availability[SDR_ITBBU]',
    'availCounty.explainCol': 'County value = equal-weight average over the sites of that county that **have data in the period**: each site is first averaged over its own days with data, then sites are averaged one vote each. A county with few sites swings on a single site.\nMetric: {{metric}} (UME MS SLA site-level daily table).\nGrey number = sites with data; up/down arrow = change vs the previous period in percentage points.\nHover a number for that cell breakdown; click it to drill into site detail.',
    'availCounty.explainKpi': 'Whole-network value = arithmetic mean of the county values shown in the table for that technology — **one vote per county**, regardless of county size, and the "Unmatched sites" row is excluded.\nSo it matches the table rows, but it is **not** a site-weighted real network availability.\nMetric: {{metric}}.\nBottom line {{n}}/{{total}} = counties off target / counties with data. Click the card to drill into whole-network site detail.',
    'availCounty.explainSiteAvail': 'Arithmetic mean over the days this site **has data** in the period (missing days are skipped, never counted as 0) — the same measure as the county values.\nMetric: {{metric}}.',
    'availCounty.explainSiteDays': 'Days that fed the average above, not the total days of the period. Daily granularity gives at most 1; weekly gives however many days were synced.',
    'availCounty.explainDaily': 'Raw reading of that day from the UME site-level daily table, **not averaged**. A dash means no data was synced, not 0% availability.',
    'availCounty.tip.avg': 'Equal-weight average of {{n}} sites with data; {{below}} of them below the {{thr}}% threshold',
    'availCounty.tip.sample': 'Sample: {{d}} site-days (site x day, missing days excluded)',
