        'nur.excludeLoadFail': 'Exclude list load failed (degraded to empty)',
        'nur.excludeY': 'Y — subtract listed tickets',
        'nur.excludeN': 'N — all tickets (same as blank)',
        'nur.excludeAll': 'All tickets',
