    // Data Overview remarks
    'overview.explain.totalTables': '**Total number of tables**: the endpoint `/api/db/info` lists them and the count is len() of that list.\n⚠ Tables starting with `_` are **not** excluded here (the previous wording claimed they were; corrected against the code on 2026-11-04).\nTwo dialect branches (`backend/routers/system.py:99-109`): in PG it reads `information_schema.tables` for `current_schemas(false)` keeping only **BASE TABLE** (views excluded), names carry the schema prefix such as `app.eflow_tt`; in SQLite it uses `list_table_names`, which only excludes `sqlite_%`.',
    'overview.explain.totalRows': 'The **sum of row counts** across all tables: the backend runs `SELECT COUNT(*)` for every table and adds them up (`system.py:110-118`).\nMeasured, not estimated (no `pg_class.reltuples` shortcut); no time or status filter, and internal tables are not excluded.\nThat is why this total includes `_`-prefixed tables, `analysis_archive` and `uploaded_files`, while the Top 10 below excludes them — the two not adding up is a caliber difference, not lost data.',
    'overview.explain.coreTables': '"Core tables" = counted **in the frontend** over the table list the API sends, keeping names that do not start with `_` (the endpoint does not send this field).\n⚠ In PG mode table names carry a schema prefix (`app.xxx`), so the test is almost always true → core tables equals the total; only in SQLite mode do `_`-prefixed tables actually get filtered out.',
    'overview.tip.totalTables': 'This figure = API total_tables = **{n}** (the length of the table list the backend built)\n`_`-prefixed internal tables are included; PG counts BASE TABLE only (views excluded), SQLite excludes only `sqlite_%`',
    'overview.tip.totalRows': 'This figure = API total_rows = **{n}**\nFormula: `SELECT COUNT(*)` executed per table, then added up — measured, not an estimate\nIncludes `_`-prefixed internal tables plus archive/upload tables, so it is **larger** than the sum of the Top 10 bars (which excludes those)',
    'overview.tip.coreTables': 'This figure = **{core}**, counted in the frontend over the API table list as "names not starting with `_`" (the API does not send this field)\nThe total is {all}: the difference is the number of `_`-prefixed internal tables\n⚠ In PG, names carry a `schema.` prefix so this test is nearly always true — the two figures being equal is expected',
    'overview.tip.status': 'This card is not a computed figure: it shows "OK" whenever `/api/db/info` returns, and the page switches to an error state when it does not\nIt only says this one call succeeded — it says nothing about data freshness (for that, use Task Management)',
    'overview.explain.rank': 'The Top 10 is **sorted in the frontend**: the API `tables` payload is neither sorted nor trimmed; the page filters out `_`-prefixed tables, `analysis_archive` and `uploaded_files`, then sorts by rows descending and takes 10 (`Overview.tsx:40-43`).\nEach bar = the measured `SELECT COUNT(*)` of that table.\n⚠ So "the Top 10 does not sum to the header total" is expected: the header total includes the tables excluded here.',
    'overview.explain.dist': 'This pie uses **the same filtered set** as the bars on the left (also excluding `_`-prefixed, `analysis_archive` and `uploaded_files`) — the first 10 of it.\nThe percentages are computed by ECharts over **the row sum of those 10 tables**, not over the whole database: they add to 100%, which is not the same as "these 10 tables hold 100% of the data".',

    // GIS Map remarks
    'gis.explain.note': 'Historic mode: TT/WO aggregated by alarm_occur_time, time window end is exclusive (+1 day); only sites with non-null, non-zero lat/lng are included.\nRealtime mode: shows only sites with ≥1 realtime alarm (no time filter); overdue = (now − servertime) > assign_delay (no 1.1 tolerance here).\nMarker size from tt_count + wo_count (>50→10, >20→8, >5→6).',

    // Analysis Dashboard remarks
    'dashboard.explain.note': 'Charts are auto-generated from the selected table\'s column profile (distribution / mean comparison / trend / quality radar / SLA·status heatmap), not fixed KPIs.\n⚠ Every chart is computed over **a sample of at most 10000 rows**: the backend runs `SELECT * FROM table LIMIT 10000` (`routers/analysis.py:60`, no ORDER BY, so it is the first 10k rows in storage order).\nThe "N rows" in the dropdown is a full-table `COUNT(*)`, while the counts and means in the charts cover only those 10k rows — on a large table the two cannot add up, which is not lost data.\nLinked filter: clicking a pie/bar slice drills down and filters that column — but it is **frontend highlighting only**, no refetch happens, so the numbers you still see are the whole-sample figures.',
    'dashboard.explain.pie': 'Pie = that column\'s `value_counts().head(10)` (`analysis.py:237`): **only the 10 most frequent values** are taken.\nSlice percentages are computed by ECharts over **the sum of those 10 values** — everything ranked 11th and below is not in the denominator, so "100%" does not mean "all rows of this column".\nThe counts are also taken over the ≤10000-row sample.',
    'dashboard.explain.bar': 'Bar = `groupby().mean()` on the category column then `dropna().head(15)` (`analysis.py:271`): each bar is the **arithmetic mean of the numeric column** for that category, not a sum and not weighted.\n⚠ The backend turns NaN into 0 (`analysis.py:280`, the `else 0` branch), so a bar at 0 can mean "genuinely zero" or "no numeric value to average".\nOnly the first 15 categories are shown; the mean is computed over the ≤10000-row sample.',
    'dashboard.explain.line': 'Line = `groupby().size()` on the date column then `tail(60)` (`analysis.py:300`): the y-axis is a **row count per date**, not a sum or mean of any metric.\nThe last 60 dates are kept; counts come from the ≤10000-row sample, so if the sample was cut by LIMIT, later dates appear thinner.',
    'dashboard.explain.radar': 'Radar = a quality score per numeric column: `score = 100 − null_rate − min(issue_count × 10, 50)`, floored at 0 (`analysis.py:309-310`).\nnull_rate = `isna / rows × 100` inside the sample (`services/profiler.py:58`); issue_count comes from the column profile issues_summary.\nThe axis maximum of 100 is hard-coded in the frontend; this is a **heuristic ruler**, not a business compliance rate.',
    'dashboard.explain.heat': 'Heatmap = `pd.crosstab(category_column, SLA/status_column).head(15)` (`analysis.py:324-331` and `:354-361`): each cell is a **row count for that combination**, drawing only the first 15 categories.\n⚠ Empty combinations are stored as 0 by the backend (`else 0`), and the colour scale maximum is computed by the frontend with `Math.max(...)`, so it is not the maximum of the whole table.',
    'dashboard.explain.other': 'The figures in this chart are also computed over **a sample of at most 10000 rows** (`SELECT * FROM table LIMIT 10000`, unsorted), which is not the same denominator as the full-table row count shown in the dropdown.',
    // Numbers inside canvas cannot carry a React bubble, so the caliber rides on the ECharts tooltip footer (short lines, literal keys)
    'dashboard.tip.pie': 'Counts and percentages come from the ≤10000-row sample; the percentage denominator is the sum of these 10 values only',
    'dashboard.tip.bar': 'Bars are the **mean** per category (not a sum, unweighted); NaN becomes 0; sample ≤10000 rows',
    'dashboard.tip.line': 'The axis is a **row count per date** (not a sum or mean of any metric); sample ≤10000 rows',
    'dashboard.tip.radar': 'Quality score = 100 − null_rate − min(issue_count × 10, 50); heuristic, with the 100 ceiling hard-coded in the frontend',
    'dashboard.tip.heat': 'Each cell is a **row count for that combination** (sample ≤10000 rows); empty combinations are stored as 0',
    'dashboard.tip.other': 'Figures are computed over a sample of at most 10000 rows (the backend query is unsorted, so it is not the whole table)',

