    'table.mwSites': '{n} sites',
    'table.explain.rowCount': '= the **whole-table row count** from `SELECT COUNT(*)` that /tables runs per table: no time window, and unaffected by the search box or filters below. Note the local-authoritative tables (data only ever written to local SQLite) read as empty shells in the main database under pg mode and always show 0 — the page states this permanently.',
    'table.explain.colCount': '= column count of the table structure returned by /tables. The profile tab\'s total_cols means the same thing but is counted on the **sampled** DataFrame.',
    'table.explain.visibleCols': 'Showing {n} of {m} columns. n = columns you ticked in "Customize columns", m = total columns the API returned. This is a **display-layer** filter only; it changes no row or column count.',
    'table.explain.pageTotal': '= the data endpoint total = COUNT(*) **with the current search term**, not the whole-table count. Search runs a LIKE match over every column: non-text columns are CAST to text and at most the first 200 columns participate (wider tables are cut off), so "0 rows found" does not mean the data is absent.',
    'table.explain.importRows': '= API row_count: rows **written to the database by this import** (data rows, header excluded); col_count = columns parsed. For an overwrite import it is the total after overwriting.',
    'table.explain.quality': 'Quality score = 100 − (issues ÷ checks) × 100. Checks are hard-coded at **5 per column** while a column can trigger at most 4 (outlier / null rate / constant / skewed), so the floor is 20, rounded to 1 decimal. Null rate >50% is an error, >20% a warning (mutually exclusive).',
    'table.explain.sampleRows': 'This {n} is the **sampled row count**: the profiling SQL is hard-coded to `SELECT * LIMIT 10000` with no ORDER BY, so it takes the first 10,000 rows the database returns — not a random sample. The whole-table count is the header tag.',
    'table.explain.sampleCols': '= API total_cols: columns of the sampled DataFrame. Every profiling metric below (null rate, unique count, quality score) is computed on the **same sample of up to 10,000 rows**.',
    'table.explain.issueListLen': '= frontend length of profile.issues_summary: issue records the backend collected column by column. One column can contribute several, so this is not "the number of bad columns".',
    'table.profileSampled': 'Profiling uses a **sample of the first {n} rows** (backend SQL hard-coded LIMIT 10000, no ORDER BY, not random): quality score, null rates and unique counts describe this sample only. See the header row-count tag for the whole table.',
    'table.explain.colNullRate': 'Column null rate % = API null_rate = null_count ÷ total × 100, where total is the **sampled** row count. The colour thresholds (>50 red, >20 amber) are display emphasis only, not a business verdict.',
    'table.explain.cellNullRate': '{name}: API null_rate = {pct}%, i.e. {nulls} ÷ {total} (sampled rows, not the whole table).',
    'table.explain.colUnique': 'Column distinct-value count = API unique_count (pandas nunique, **nulls excluded**). Read it next to the null rate: a column that is 90% empty with three values has a tiny unique count yet is far from clean.',
    'table.explain.cellUnique': '{name}: API unique_count = {uniq} over {total} sampled rows.',
    'table.explain.colIssue': 'Column issue count = API issue_count, one increment per hit among the four checks (outlier / null rate / constant column / skewed distribution), at most 4 per column. The badge only appears when this is above 0.',
    'table.explain.cellIssue': '{name}: API issue_count = {n}. Every record is listed in profile.issues_summary (this endpoint does not truncate, unlike the upload page which sends the first 10).',
    'table.explain.cellIssueZero': '{name}: none of the four checks fired, so this shows a dash instead of a 0 badge.',
    'table.explain.mwSites': '= COUNT(*) WHERE kind = site on the kml_mw_links table: **rows tagged as sites** (the same site appearing in several links/KMLs takes one row each), not the number of distinct sites.',
    'table.explain.mwLinks': '= COUNT(*) WHERE kind = link: link rows. One A→B link is one row; there is no de-duplication by endpoint.',
    'table.explain.mwWrittenSites': '= API stats.sites: **site rows written by this import** (a per-row counter, not distinct sites).',
    'table.explain.mwWrittenLinks': '= API stats.links: link rows written by this import.',
    'table.explain.mwSkipped': '= API stats.skipped: KML elements judged invalid and **not written** during this parse — a link needs at least 2 coordinates and both endpoint names, a site needs a coordinate and a name. These are excluded from the two numbers above.',
    'table.mwLinks': '{n} links',
