    // Site-status legend (2026-10-30, aligned with the realtime alarm page):
    // buckets and colors share one source with ?page=realtime_alarm
    // (gismap/types.ts LEGEND_COLORS); the overlay itself reuses
    // gismap/MapLegendOverlay, and its title / group names reuse gis.legendTitle
    // and gis.legendGroup.* — so only the person-page-specific wording is kept
    // here (the "open WO" bucket).
    'person.siteLegend.note': 'Each bucket = the number of **sites** painted with that colour on the map, matching the dots exactly. Precedence: Realtime Alarm (Overdue) > this person has an open WO > site has an alarm TT > Realtime Alarm (On Time) > VIP Site > no status. Dot size also shows urgency (bigger = more urgent). "This person has an open WO" is specific to the person page — it means that **person** still has an open work order at that site, which is not the same as the realtime alarm page\'s "WO linked from the site\'s alarm".',
    'person.siteLegend.wo': 'This person has an open WO',
    'person.siteLegend.woHint': 'That **person** still has an open work order at this site (work orders with an uncleared alarm are counted in the "Uncleared" column instead, they do not get their own colour bucket). This bucket is specific to the person page — it is not the same as the realtime alarm page\'s "WO linked from the site\'s alarm".',
    'person.chartByPerson': 'WO by person, Top 10 (stacked: uncleared / other open / closed)',
