    'person.colClosedWo': 'Closed WO',
    'person.colTt': 'TT (rows)',
    'person.explain.colUncleared': 'This column = API by_person.uncleared: WO rows in the window whose **alarm is still uncleared** for this person. Red bold only means "there are uncleared rows" — it is not a pass/fail line.',
    'person.explain.colOpen': 'This column = API by_person.open: unclosed WO rows for this person within the last {days} days, computed by one backend scan; nothing is recomputed here.',
    'person.explain.colClosed': 'This column = API by_person.closed: closed WO rows for this person within the last {days} days (status starting with "closed", Closed_Confirmed included).',
    'person.explain.colTt': 'This column = API by_person.tt_total: **WO rows carrying a tt_no** for this person, counted per row, not distinct TT numbers (several WOs on one TT each count once).',
    'person.tip.peopleFe': 'Numerator {with} = FE staff with valid coordinates, denominator {total} = all FE staff (person.isfe = Yes). Both come straight from the API coverage block; nothing is recomputed here.',
    'person.tip.peopleAll': 'The API also carries an unfiltered pair {wc} / {ta} = map pins / person table rows, with **no FE filter** — deliberately not used as the denominator, otherwise staff with coordinates but outside FE would inflate the ratio.',
    'person.tip.peopleNoWindow': 'The staff roster does not depend on the {days}-day window; only the work-order figures do.',
    'person.tip.sumRows': 'This page sums the API field {field} over the {n} rows currently in the table, giving {value}; each person value comes from one backend scan — the page only adds them up.',
    'person.tip.unclearedCaliber': '"Uncleared" = eflow_wo.alarm_clear_time is empty **and** the status is not closed (_is_uncleared in personnel.py). It is a different concept from "unclosed WO" — a Wait For Confirm ticket is often alarm-cleared but still open in the flow.',
    'person.tip.openCaliber': '"Unclosed" = status does not start with "closed". The window filters alarm_occur_time to the last {days} days (fixed on this page; it does not follow the GIS time control).',
    'person.tip.totalCaliber': '"Total" = WO rows for this person in the window; each row falls into either unclosed or closed, so **unclosed + closed = total**. Ownership rule: one WO may list both last_processer and current_handler, de-duplicated per person.',
    'person.tip.byStatus': 'The API also returns by_status (unclosed {open} / closed {closed}): it counts **all** WO rows in the window, including those not attributable to a person, so summing the table is usually smaller.',
    'person.tip.sitesNoSel': 'Shows — while nobody is selected: the API does not publish a de-duplicated site count across all staff (by_county has no such column), so no number is invented. Select a person and this becomes their managed-site count.',
    'person.tip.sitesSel': '{name}: managed-site count = {n} rows returned by the managed-sites API, no further filtering here.',
    'person.tip.sitesAlarm': 'Of these, {alarm} sites currently have an active alarm (per-row has_alarm from the API; this page only counts them).',
