    'person.tip.cellTt': '{name}: WO rows carrying a tt_no = {v} (unclosed {open} / closed {closed}). Per row, not distinct TT numbers.',
    'person.tip.cellDrill': 'Click "View WOs" on this row to drill into the list — same source and same window, so the row count matches.',
