    'gis.kpi.explainQuality': 'Source: site-level daily table ms_sla_*_SITE (the ms_sla_ prefix is dropped in PostgreSQL), one row per site per day.\nRatio columns are stored as 0~1 and shown as percentages, including congestion, drop and PRB utilization.\nRows of the same day under several BSC/RNC are averaged.\n4G matches by site_id; 2G/3G IDs belong to another numbering scheme, so it falls back to site-name matching.',
    'gis.kpi.explainVolume': 'Source: the same site-level daily table as network quality, one row per site per day.\nTraffic columns (CS Erl, GB, Mbps, RRC users, outage minutes) keep their original scale, **one y-axis per unit**.\nWhen a site sits under several BSC/RNC the upstream writes one row per ID per day and the API **sums** the traffic columns into the site total; values come from the API, never recalculated in the browser.',

