    // Data Sync / Task Management
    'nav.sync': 'Task Manager',
    'sync.title': 'Data Sync',
    'sync.subtitle': 'eFlow API Sync · Scheduled Task · Manual Trigger',
    'sync.taskManager': 'Task Manager',
    'sync.taskManagerDesc': 'Manage scheduling and execution of all automated tasks',
    // Status statistics module
    'sync.statTitle': 'Status Overview',
    'sync.statHint': 'Click a status card to filter; click again or click "All" to clear',
    'sync.explain.cardAll': '= number of task rows returned by the /tasks endpoint in one call (the backend lists the TASK_SPECS registry, **including disabled tasks**). The page applies no further filter.',
    'sync.explain.cardRunning': '"Running" = a hit from the frontend poll of /tasks/running (queue and in-memory state), or the local flag set when you clicked "Run" here — it does **not** read the database run records, so right after a refresh it can be lower than reality.',
    'sync.explain.cardSuccess': '"Success" = the **latest** run record of the task has success=true (the backend takes the first of recent_runs by MAX(id)). It does not mean the task succeeded over the last N days.',
    'sync.explain.cardFailed': '"Failed" = the latest run record has success=false and the task is not currently running. It reflects the **last attempt**, not the number of failures in a window — that count lives in the "failure clusters" dialog.',
    'sync.explain.cardDisabled': '"Disabled" = the API returns enabled=false. Actual enable/disable state comes from the task_schedule_config table, which overrides the TASK_SPECS default and takes effect immediately without a restart.',
    'sync.explain.cardUnknown': '"No record" = the task is enabled but the database holds **no run record at all** (newly registered or never run). Kept as its own card on purpose: without it the status cards would sum to less than "All" and read as a counting bug.',
    'sync.explain.cardSum': 'Every task falls into exactly one bucket (the same function drives the count and the filter), so the five status cards sum to "All" = {all}. Clicking a card switches the filter, so the number and the filtered list share one judgement.',
    'sync.explain.toggleCount': 'Numerator {enabled} = tasks in the list with enabled=true; denominator {all} = all task rows returned by the API (**including exempt and manually stopped ones**, so a 73-row list reports x/73). The master switch itself only looks at non-exempt, non-manually-stopped tasks — deliberately a different denominator, otherwise it would hit the "no matter what I click it stays off" trap.',
    'sync.explain.listCount': 'Numerator {shown} = rows after the current filter; denominator {all} = all task rows from the API. Two deliberate scopes.',
    'sync.explain.failBanner': 'The banner N = {count} counts **tasks** whose latest run failed and that are not currently running (same judgement as the "Failed" card). It is tasks, not failure occurrences.',
    'sync.explain.groupCount': 'The {n} in brackets = task cards rendered for this group under the current filter; grouping itself comes from an API field and is not filtered further.',
    'sync.explain.timelineCount': '= tasks that appear on the timeline with at least one run record ({n}); tasks the API never reported a run for are not drawn. Total tasks are {all}, and the difference is exactly the "No record" card.',
    'sync.explain.elapsed': '= elapsed_seconds of the latest run record from the API (seconds, 1 decimal). A dash means the record carries no duration — it is **not** a 0-second run. (task id={id})',
    'sync.explain.aggTotal': 'Last {days} days: "{n} failures / {k} clusters". The /tasks/failures endpoint takes success=0 rows in that window and groups them by the **first line of the error**; {n} = sum of the cluster counts, {k} = number of clusters.',
    'sync.aggTruncated': '⚠ The endpoint SQL fetched only the newest {scanned} failure rows (last {days} days). Once the cap is reached older failures are not scanned — the "N failures" above means **at least** N, not the true window total.',
    'sync.explain.clusterCount': '×{n} = how often this cluster (first error line "{first}") appears among the fetched records; taken from API clusters[].count.',
    'sync.explain.taskFailCount': '{tid} ×{n} = failures of this task inside this cluster (API clusters[].tasks map). Clicking the tag opens that task\'s run history.',
    'sync.explain.thTotal': 'Total runs {n} = COUNT(*) from the stats endpoint (all rows of this task in task_execution_log), of which {ok} succeeded and {bad} failed. That table keeps 7 days by default (env TASK_LOG_RETENTION_DAYS), so this is not "since launch".',
    'sync.explain.thSuccess': 'Success rate {rate} = successful runs ÷ total runs over all retained rows of this task. The 0.8 green threshold is only **frontend colouring**, not a business pass mark.',
    'sync.explain.thAvg': 'Average {v} = API AVG(elapsed_seconds): the arithmetic mean over retained runs, **failed runs included**.',
    'sync.explain.thMax': 'Maximum {v} = API MAX(elapsed_seconds): the real duration of a single record, unrelated to any timeout setting.',
    'sync.explain.thShown': 'This dialog fetched the newest 200 records; {shown} of {fetched} are shown. "Load more" adds 20 at a time. Older records may already be outside the log retention window.',
    'sync.explain.ghTotal': '= the /tasks/history total = COUNT(*) on task_execution_log **with the current filters** (task, status, time range, keyword). The table keeps 7 days by default (env TASK_LOG_RETENTION_DAYS), so this is not "every run ever"; test tasks whose id starts with __t_ are already excluded by the backend.',
