    'ap.explain.cardOpen': 'API /ap/stats "open": rows grouped by status, then DRAFT / ASSIGNED / ACKNOWLEDGED / IN_PROGRESS / PENDING_REVIEW / REJECTED summed (backend OPEN_STATUSES, **excluding** COMPLETED and CANCELLED).',
    'ap.explain.cardOpenScope': '⚠ The scope is hard-coded to **mine** in the backend: only actions whose owner_username or created_by matches the current account are counted. The tabs above (my queue / awaiting my review / all) **change the list below only, never these four cards**.',
    'ap.explain.cardInProgress': '= API in_progress = by_status entries whose status is exactly IN_PROGRESS, one of the states summed into the "Open" card. Also mine-scoped.',
    'ap.explain.cardPendingReview': '= API pending_review = rows whose status is exactly PENDING_REVIEW (mine scope).',
    'ap.explain.cardOverdue': '= API overdue: a **separate COUNT(*)** with due_at not null **and** due_at < server current time **and** status still in OPEN_STATUSES — it is not re-filtered from the "Open" card. Time uses the server local clock (store._now), not the browser clock. Also mine-scoped.',
    'ap.explain.progress': 'Progress % = API progress field (integer 0-100 stored by the backend, written on each "update progress" action). The page only applies Number() fallback; it never derives progress from the status.',
    'ap.explain.progressCell': 'API progress for this row (id={id}) = {v}%. The backend clamps submitted values to 0-100. A displayed 0% means either no progress was ever submitted (schema default 0) or someone entered 0 — the API does not distinguish the two.',
    'ap.explain.updateProgress': 'Progress recorded by this update = {v}% ({at}). The task row and the list show the **latest** submitted value.',
