    // Packet Loss metric explanations
    'pl.explain.totalSites': 'Total sites monitored for packet loss.\nSource: Packet Loss Status Report site master data (lte_pl.sqlite3, last 7 complete calendar days, hourly granularity; the unfinished current day is excluded).',
    'pl.explain.critical': 'Sites whose FINAL_STATUS is Critical.\nCalculation: STATUS is derived from the 0-23 flag block (a flag = 1 when the same hour exceeds 0.5% PL in each of the last 3 days; all-zero flags = OK). STATUS≠OK and Last 1 day Max PL ≥ 5% = Critical.\nLast 1 day Max PL = max hourly PL of the latest complete day (00-23h).',
    'pl.explain.major': 'Sites whose FINAL_STATUS is Major.\nCalculation: STATUS≠OK and Last 1 day Max PL in [1%, 5%) = Major.',
    'pl.explain.minor': 'Sites whose FINAL_STATUS is Minor.\nCalculation: STATUS≠OK and Last 1 day Max PL in [0.5%, 1%) = Minor.',
    'pl.explain.warning': 'Sites whose FINAL_STATUS is Warning.\nCalculation: STATUS≠OK and Last 1 day Max PL in [0.1%, 0.5%) = Warning.',
    'pl.explain.noPacketLoss': 'Sites considered normal.\nCalculation: STATUS=OK (all 0-23 flags are 0, i.e. no hour exceeded 0.5% PL in each of the last 3 days) is forced to No Packet loss; or STATUS≠OK but Last 1 day Max PL < 0.1%.',
    'pl.explain.affectedSites': 'Affected Sites = Critical + Major (STATUS≠OK and Last 1 day Max PL ≥ 1%).\nMatches the "Affected Sites (Critical+Major)" row in the Excel report Summary sheet; Minor/Warning are not included.',
    'pl.explain.granularity': 'Data granularity: last 7 complete calendar days, hourly (SDR + IPRAN IPPD packet loss rate); the unfinished current day is excluded.\nSTATUS rule: an hour is flagged 1 when its PL exceeds 0.5% in each of the last 3 days at the same hour; all-zero flags -> OK, otherwise NOK.\nSDR = Software Defined Radio (3G/2G); IPRAN = IP backhaul transport network.',
    // ---- Number hover additions (2026-11-04, AGENTS.md 3.3c); calibers verified in routers/packet_loss_dashboard.py ----
    'pl.explain.dist': 'These three charts **do not share a denominator** — do not reconcile them against each other:\n· Status pie = site_pl_summary counted row by row on FinalStatus (it includes sites without coordinates); the slice percentage is computed by ECharts over **the slices currently shown** — hiding a band through the legend recomputes it, so it no longer matches the pct the backend sends (whose denominator is always all sites).\n· Region bars = **non-OK sites only** (Minor and Warning included), so their site total is **larger** than the "Affected Sites = Critical + Major" figure at the top.\n· The daily-trend median **uses only readings greater than 0 for that day**: roughly 59% of hourly readings are 0, so a full median collapses to 0 and stops being meaningful; "affected sites" counts distinct Managed Elements above 0.1%, over the last 7 complete calendar days only (the current day is excluded).',
    'pl.explain.topSites': 'Top sites: window = the **last 24 complete hours** (the current day dropped); for each site the median of **all** its readings (zeros included) is taken, joined by code→name, then the first 15 are shown.\nWhy the trend uses a non-zero median but this one includes zeros: at site level a non-zero median would make "half a day normal, half a day fully down" and "fully down all day" both land on 100, which destroys the ranking value (`packet_loss_dashboard.py:192-238`).\nAffected hours = the number of hours in the window with packet loss above 0; the two measures are not a ratio of each other.',
    'pl.tip.drillCount': '**{n}** rows now = detail rows **after the search box filter**; this call returned {total} rows from the API.\n⚠ The API fetches detail up to a cap, so {total} is already post-truncation — "rows here" is not "all sites in that status". Narrow the filter or use the export if you need the full set.',

