    // ---- Number hover explanations (2026-11-05, AGENTS.md 3.3c) ----
    'batt.clientCalcNote': '⚠ This card is **computed in the frontend over the rows left after the on-page filters**. The endpoint `/api/battery-dashboard/all` also returns a field of the same name under `kpi`,\nbut that one is the **unfiltered total** (measured with no filters: API total 1532 / sites 208, while the cards show 352 / 48 with "fresh only" on).\nA mismatch normally means a filter is active, not that the data is wrong — reconciled value by value on 2026-11-05: apart from "total" and "sites" being two different semantics,\nand the averages differing only in precision (frontend keeps 1 decimal, the API 2), the other six figures and all five distributions are identical.\nKeeping the frontend computation was a deliberate, user-approved choice: the six filters must update the cards instantly, and reading the API instead would freeze them.',
    'batt.explain.socDist': 'The bucket boundaries are **hard-coded in the frontend**: ≤0 empty, <20 critical, <50 low, <80, ≥80 (`BatteryDashboard.tsx:240-242`).\n⚠ They do not follow the configurable threshold: the "SOC critical" card above uses `meta.soc_critical` from the API (it moves when the setting changes)\nwhile neither this chart\'s boundaries nor its labels move — the two "20%" on this page come from different places, so do not treat them as one number.\nThe sample follows the "fresh only" switch (only readings within 24h when it is on).',
    'batt.explain.healthDist': 'Boundaries come from the API thresholds (`health_degraded` default 90, `health_good` default 95), but the **bucket label text is hard-coded**\n(`80-90% (Degraded)` / `90-95% (Fair)`, `:243-245`).\n⚠ If someone changes the thresholds, the labels stop matching the real intervals — trust the wording in this bubble, not the label.\n`No Data` counts batteries whose health is empty (the majority here, so this chart mostly shows reporting gaps rather than battery condition).',
    'batt.explain.statusDist': 'Any reading that is neither `Charge` nor `Discharge` is bucketed as `Unknown` (`:290-291`) — it does not mean "unknown device", only that the status field is not one of those two words.\nThe sample follows the same "fresh only" switch as the SOC and health charts; `discharging` is often read as a mains-failure proxy, but it is a **current-state snapshot**, not a count of past discharge events.',
    'batt.explain.freshDist': 'This chart counts **all rows** and does not narrow with the "fresh only" switch (unlike the three charts above).\nThe freshness verdict is computed **at ingest time**: `last_update` is the maximum updateTime of the three measurement points, ≤24h fresh, ≤7d delayed, >7d stale, no timestamp no_data\n(`battery_kpi_service.py:197-209`); the three thresholds can be overridden by battery_meta, so "24 hours / 7 days" are **defaults, not hard-coded values**.',
    'batt.tip.alarmBadges': 'The three badges = the API `alarms` list **re-counted over the sites left by the current filters** (`:329-334`).\n⚠ The API also returns `alarm_summary`, which is **independent of the filters** (with no filters the two agree); a mismatch usually means a filter is active.\nThe seven alarm rules (SOC<20, health<90, not updated for 7/30 days, etc.) live in `battery_dashboard.py:152-204`;\nthe alarm list is capped at 2000 rows (`:377`), so once the cap is hit these counts are lower than reality.',
