    // ===== CN KPI dashboard (native rebuild of my-finebi "CN KPI") =====
    'nav.cnKpi': 'CN KPI',
    'nav.cnKpi5mins': 'CN KPI 5-Min',

    // ===== CN KPI 5-minute dashboard (Day0/Day1/Day7 overlay) =====
    // Data is written every 15 min by the cnn_kpi_sync_5mins task into the 5mins_* tables
    // The page title is rendered by the app-wide Header (menu label); the page keeps only the stats bar
    'cnkpi5.barHint': 'Each chart lines up the same clock time for today, yesterday and 7 days ago (the same weekday), so both the intraday shape and the week-over-week gap are visible',
    'cnkpi5.noGranularity': 'No data',
    'cnkpi5.noData': 'No data',
    'cnkpi5.queryFail': 'Query failed',
    'cnkpi5.loadFail': 'Failed to load dashboard data',
    'cnkpi5.time': 'Time',
    'cnkpi5.value': 'value',
    'cnkpi5.rows': 'rows',
    'cnkpi5.day0': 'Day0 (today)',
    'cnkpi5.day1': 'Day1 (yesterday)',
    'cnkpi5.day7': 'Day7 (7 days ago)',
    'cnkpi5.summary': '{{ok}}/{{total}} widgets with data',
    'cnkpi5.legendHint': 'Each chart shows the same clock time for today, yesterday and 7 days ago, so the intraday trend and the week-over-week level can be compared directly',
    // Day7 only draws once the tables hold 8 days of history (the sync window is
    // "yesterday -> now", older days accumulate through upsert)
    'cnkpi5.day7Absent': 'No Day7 (7 days ago) history yet',
    'cnkpi5.emptyBanner': '{{n}} widget(s) have no data yet (not a fault)',
    'cnkpi5.emptyWhy': 'Usually because the upstream template for that KPI does not expose this granularity, or the task has not collected the latest batch yet.',
    // Mixed granularity: xGW License / xGW CPU / 3G FDD use the upstream 15-minute
    // templates (the originals had no 5-minute tier); the other 5 use 5-minute.
    'cnkpi5.mixedGranularity': 'Some widgets are 15-minute',
    'cnkpi5.mixedGranularityHint': 'xGW License, xGW CPU and 3G FDD use the upstream 15-minute templates (the originals had no 5-minute tier); the other 5 are 5-minute. The 15-minute widgets have fewer points, but the x axis is still clock time, so they compare directly.',
    // The whole notes block is collapsed by default (AGENTS.md 三.3); the title is the toggle
    'cnkpi5.note.title': 'Data notes (click to expand)',
    'cnkpi5.note.sec.granularity': '1) Granularity: 5-minute and 15-minute mixed',
    'cnkpi5.note.sec.empty': '2) Why some widgets are empty',
    // "today vs yesterday" tag on each card: yesterday is cut at the same clock time
    // as today's last point, otherwise an unfinished day would look artificially low
    'cnkpi5.vsDay1': 'vs yesterday {{pct}}',
    'cnkpi5.vsDay1Hint': 'Mean up to {{time}}: today vs the same time window yesterday (yesterday cut at the same clock time), so the unfinished-day truncation is removed. Fluctuation within ±10% is normal; beyond that the tag turns orange.',
    'cnkpi5.vsDay1NoBase': 'vs yesterday —',
    // ---- CN KPI 5-mins: per-widget and header number hover explain (AGENTS.md 3.3c) ----
    'cnkpi5.explain.common': 'Day bucketing and the x-axis both use `substr("End Time", …)` (not Begin Time): Day0 = today, Day1 = yesterday, Day7 = 7 days ago (same weekday).\nThe window holds only these **three days**, not a continuous 7, and aggregates GROUP BY (HH:MM, Day).\nWhether Day7 has a line depends on how many days the warehouse has accumulated, not on this page.',
    'cnkpi5.explain.emptyCard': 'This card has no curve because the API flagged it empty (not an error). Reason: {reason}',
    'cnkpi5.explain.vlr': 'Value = SUM("Number of Subscribers in VLR") — subscribers summed within the same 5-minute window, unit: persons.',
    'cnkpi5.explain.voice': 'Value = ROUND(SUM("Seized Traffic(Erl)"), 2) — traffic summed in Erlang, 2 decimals.',
    'cnkpi5.explain.dataSub': 'Value = ROUND(SUM(GSM + UMTS + EPS "mean attached subscribers"), 0): the three columns are added row-wise first, then summed; missing columns count as 0 via COALESCE(...,0).',
    'cnkpi5.explain.4gTraffic': 'Value = ROUND(SUM("Byte of downlink data packets received via SGi interface per APN(Byte)") / 1e9, 3) — bytes converted to **GB** (1e9, not GiB), 3 decimals.',
    'cnkpi5.explain.rg30': 'Value = ROUND(SUM("Bytes of flows of downlink packets based RG(Byte)") / 1e9, 3), restricted to **"Measurement Object" = 30**. The RG-30/12/11/6 cards split one table by that number and never overlap.',
    'cnkpi5.explain.rg12': 'Value = ROUND(SUM("Bytes of flows of downlink packets based RG(Byte)") / 1e9, 3), restricted to **"Measurement Object" = 12**. The RG-30/12/11/6 cards split one table by that number and never overlap.',
    'cnkpi5.explain.rg11': 'Value = ROUND(SUM("Bytes of flows of downlink packets based RG(Byte)") / 1e9, 3), restricted to **"Measurement Object" = 11**. The RG-30/12/11/6 cards split one table by that number and never overlap.',
    'cnkpi5.explain.rg6': 'Value = ROUND(SUM("Bytes of flows of downlink packets based RG(Byte)") / 1e9, 3), restricted to **"Measurement Object" = 6**. The RG-30/12/11/6 cards split one table by that number and never overlap.',
    'cnkpi5.explain.xgwLicense': 'Value = ROUND(AVG("Throughput Usage(%)"), 2) — an **arithmetic mean of percentages**, not traffic-weighted and not a peak.\n⚠ Upstream only publishes a **15-minute** template for this one, so it has roughly 1/3 as many points as the other cards — **sparse points are not missing data**.',
    'cnkpi5.explain.xgwCpu': 'Value = ROUND(AVG("Peak usage ratio of UP\'s vCPU(%)"), 2) — each row is already a peak vCPU ratio, and this averages those 15-minute rows (**mean, not maximum**).\n⚠ 15-minute cadence: about 1/3 as many points as the other cards.',
    'cnkpi5.explain.3gTraffic': 'Value = ROUND(SUM("Bytes of downlink data packets received via Gi interface per APN(Byte)") / 1e9, 3) — bytes converted to GB.\n⚠ The 3G column is **Bytes (plural)**, unlike 4G\'s "Byte …"; a singular typo does not error in SQLite — the double-quoted identifier becomes a string literal and SUM is permanently 0 (hit in practice on 2026-10-19).\n⚠ 15-minute cadence: about 1/3 as many points.',
    'cnkpi5.tip.vsFrontend': 'This percentage is computed **by the frontend** from the API rows (the API sends no pct): today\'s mean from 00:00 to now versus yesterday\'s mean truncated to the same clock time.',
    'cnkpi5.tip.vsNoBase': 'Nothing to show because there is no comparable baseline: today or yesterday has no point in that span, or yesterday\'s mean for the span is 0 (not divisible).',
    'cnkpi5.tip.summary': '{{ok}}/{{total}} = widgets with data over total widgets (API meta.count). **Empty and failed widgets are both excluded** from "with data".',
    'cnkpi5.tip.elapsed': '{{ms}}ms = the backend\'s total wall time to fetch these 11 widgets concurrently (remote read-only API, not local SQLite).\nCache: {{cached}} (TTL 30 seconds, so a hit costs almost nothing).',
    'cnkpi5.tip.cachedYes': 'this response came from cache',
    'cnkpi5.tip.cachedNo': 'this response was fetched live (the next click within 30s hits the cache)',
    'cnkpi5.tip.failed': '{{n}} = API meta.failed: widgets whose **query errored** (empty ones do not count). Mostly a not-yet-created remote table or a timeout — see the red text on the affected card.',
    'cnkpi5.exportSource': 'Data source',
    'cnkpi5.exportGenerated': 'Generated at',

