    // ---- CN KPI dashboard: number hover explain (AGENTS.md 3.3c) ----
    'cnkpi.tip.cardBase': 'Every point on the chart is the raw value returned by this SQL; the page does **no secondary computation** (no gap filling, no smoothing, no unit conversion).',
    'cnkpi.tip.rows': '{{n}} rows × {{cols}} columns returned',
    'cnkpi.tip.granDay': 'Actual granularity: **day** (inferred from the dates in the returned rows, not hard-coded)',
    'cnkpi.tip.granMonth': 'Actual granularity: **month** ⚠ each point is one calendar month, not one day',
    'cnkpi.tip.degradedDay': 'The primary (EMS daily) table had no data for this period; the auto-synced table is used instead (original: {{from}})',
    'cnkpi.tip.degradedMonthly': 'Neither the daily nor the UME daily source returned data; downgraded to the **monthly table** (original: {{from}})',
    'cnkpi.tip.sql': 'The SQL actually executed by the backend (copy it to verify):\n{{sql}}',
    'cnkpi.tip.headerKpi': '{{title}} = the **first column of the first row** of that widget\'s result, currently "{{v}}". Nothing else is computed here.\nIts SQL carries no date placeholders, so this value does not change with the date range.',
    'cnkpi.tip.db': 'Data source: {{db}} @ {{host}} — a remote read-only HTTP API, not a local database',
    'cnkpi.tip.elapsed': '{{n}} = widget count (API meta.count); {{ms}}ms = backend concurrent fetch time; cache: {{cached}}',
