    'cnkpi.tip.cachedNo': 'fetched live',
    'cnkpi.tip.range': 'Date range: {{start}} ~ {{end}} (the {{LO}}/{{HI}} placeholders in the SQL are replaced with these two dates)',
    'cnkpi.tip.rangeDefault': 'Date range: last 31 days by default (matching the original FineBI report); monthly widgets use the last 13 months',
    'cnkpi.tip.failed': '{{n}} = widgets whose query **errored** (empty ones do not count). Only an error if all three source tiers failed — see the red text on that card.',
    'cnkpi.calc.title': 'CN KPI data caliber',
    'cnkpi.calc.secSource': 'Source and date range',
    'cnkpi.calc.src1': 'All widgets read the remote db_ps_cs_cn over a read-only HTTP API — this database is not stored locally. Byte-to-GB conversions (/1e9) are already inside the SQL, so the page receives converted values.',
    'cnkpi.calc.src2': '{{LO}} / {{HI}} in the SQL are date placeholders: last 31 days by default, replaced with the chosen dates (strictly validated as YYYY-MM-DD, no injection surface). SQL without placeholders (single-value KPIs) ignores the range.',
    'cnkpi.calc.secTier': 'Tiered fetching (fallback order)',
    'cnkpi.calc.tier1': 'Primary (EMS daily) → fallback (UME auto-synced daily) → monthly table. **The first tier returning any row wins**, and the outcome is sent down as degraded / fallback_from / granularity.',
    'cnkpi.calc.tier2': 'So "the card has numbers" does not mean the primary table was used. Hover the card title or a number to see the actual granularity and whether a downgrade happened.',
    'cnkpi.calc.secGran': 'Granularity is inferred',
    'cnkpi.calc.gran1': 'granularity comes from _detect_granularity() looking at the date spacing in the returned rows, never hard-coded; only the monthly tier is recorded as month directly.',
    'cnkpi.calc.gran2': 'Each KPI has two same-named tables (OSS and EMS): when EMS stops updating, the widget falls back to UME or the monthly table and the curve collapses from 31 points to 1-2. That is **source state**, not a fetch bug — the "monthly" tag and the standing downgrade banner say so.',
    'cnkpi.degradedTitle': '{{n}} chart(s) use a degraded data source',
    'cnkpi.degradedMonthly': 'Daily data is missing; degraded to monthly granularity (original table {{table}}). Each point is one month — do not read it as a daily value.',
    'cnkpi.degradedFallback': 'The original table {{table}} has no recent data; an auto-synced source of the same name is used instead.',
    'cnkpi.degradedWhy': 'Cause: upstream _EMS tables are exported manually from the NMS (the chosen range determines the table granularity), so data stalls whenever no export runs.',

