    'bmm.banner.network': 'BP, FDD DL IP throughput, DL/UL PRB utilization, traffic volume and RRC users are network-side KPIs. They belong to neither operator and are shown only as trends and averages — they are not part of the head-to-head.',
    'bmm.banner.relative': 'The composite score is relative (the stronger operator scores 100), not absolute. PRB utilization and BP are displayed as percentages while the database stores decimal ratios.',
