    // ---- Number hover explanations (AGENTS.md 3.3c); calibers re-verified in bm_meta_caliber.py / bm_meta_service.py ----
    'bmm.explain.verdict': 'The verdict answers one question only: **whose mean speed is higher in the range**.\nThe lead gap = one score minus the other; wins / paired days come from the day-by-day comparison (a day counts only if both operators have data).\n⚠ On this page the **score is decided by speed alone** (`SCORE_WEIGHTS = {speed: 1.0}`, caliber:92). Network KPIs do not take part in the PK — do not read it as an overall network-quality score.',
    'bmm.tip.lead': 'Gap {n} = one score minus the other (ORANGE {o} − MTN {m}, or the reverse)\n**This subtraction runs in the frontend**: the API sends two scores, and the scores themselves are computed by the backend\nThe scores are relative (the leader is always 100), so the gap does not map to an absolute speed difference',
    'bmm.tip.verdictWins': '{brand} won {w} of {d} paired days = {r}%\nPaired days = days where the day-by-day comparison **produced a winner**; ties and days with either side missing are **out of the denominator** (unlike the Speedtest page, where ties stay in it)\nThis range: {ties} tied days, {total} days with records\nClicking drills into those days. ⚠ The drill applies the 3000-row cap first and filters winners afterwards in Python (`bm_meta_service.py:419-423`), so the row count only falls short of {w} when the range exceeds that cap — this table stores one row per day, so ordinary ranges are far below it',
    'bmm.explain.scores': 'The score uses **speed only** (`SCORE_WEIGHTS = {speed: 1.0}`): the leader always gets 100, the other gets smaller ÷ larger × 100; an exact tie scores 50 for both.\nSo this card is a "relative speed score" — it **excludes the network-side KPIs** and any coverage measure.\nClicking a score drills into that operator\'s winning days (subject to the same drill-row caveat below)',
    'bmm.tip.score': '{brand} score = **{score}** (the other operator: {other})\nFormula: speed only — own {v} versus {otherV} for the other side; the leader gets 100, the other gets smaller ÷ larger × 100\nWins: {w} days from the day-by-day comparison (ties and missing days excluded from the denominator)\n⚠ This card excludes network-side KPIs',
    'bmm.explain.speed': 'Mean speed = SQL `AVG(orange_liberia | mtn_liberia)` over the range (left-closed, right-open)\nAVG **skips NULL automatically**: a day where that operator has no data does not pull its mean\n⚠ The row count shown as days is **rows of the whole table inside the range (one number shared by both operators)**, not that operator\'s own days-with-data',
    'bmm.tip.speed': '{brand} mean speed = **{v}**\nFormula: AVG of that operator\'s raw column, skipping days where it has no data\nThe range holds {days} rows (one number for both operators — it does not mean this operator had {days} days of data)\nMin {min} / max {max}; the other operator averages {other}\nClicking the card drills into that operator\'s winning days',
    'bmm.explain.range': 'Range = MIN ~ MAX of that operator\'s raw column inside the range (read straight from SQL, no sorting, no outlier trimming)\nSo a single-day spike shows up here even when the mean looks stable',
    'bmm.tip.range': '{brand}: min **{min}** ~ max **{max}** Mbps\nMean {avg} (computed over the same rows; the extremes are not treated specially)\nTaken from {days} rows in the range (AVG/MIN/MAX all skip NULL)\nClicking the card drills into every daily record for that operator in the range',
    'bmm.tip.network': '{metric}: {hint}\nMean over the range **{v}**, min {min} / max {max}, from {days} rows\nThese columns **do not take part in the PK** (the score uses speed only) and are not attributed to either operator — they are whole-FDD network readings{ratio}',
    'bmm.tip.ratioNote': '; ratio columns are already multiplied by 100 by the backend (0.1956 → 19.56) and the page only appends the percent sign',
    'bmm.explain.trend': 'Solid lines = daily raw readings (a PK metric reads the orange/mtn columns; a network metric reads its single value)\nDashed lines = the arithmetic mean of the **last {n} non-empty points**: the buffer holds only non-null values and is trimmed by point count (`bm_meta_service.py:352-358`), so it is **not a calendar window** — with sparse data this line tracks more tightly\nThe backend sends orange_ma / mtn_ma / value_ma already computed; the frontend does not average again',
    'bmm.tip.drillCount': '**{n}** rows now = API returned={returned} (cap limit={limit}, this call {truncated})\nRange {range} (left-closed, right-open)\n⚠ Coming from a "wins" entry: the backend applies the row cap first and filters winners afterwards in Python (`bm_meta_service.py:419-423`), so this count only falls below the wins on the card when the range exceeds {limit} rows — this table stores one row per day, so ordinary ranges are far below the cap',
    'bmm.tip.drillTruncated': 'capped and truncated',
    'bmm.tip.drillFull': 'not truncated',
