    'rck.sourceDesc': 'RAN_UME cell-level availability (per cell, 2G/3G/4G), target {threshold}%. Total = Meeting + Below; Blank = roster cells with no data that day; Availability = arithmetic mean of valid cell availability.',
    'rck.generated': 'Generated',
