    // ---- RAN cells KPI: number hover explain (AGENTS.md 3.3c) ----
    'rck.explain.monthAvail': 'Monthly availability = the **arithmetic mean of the daily availability values (one vote per day)**, not weighted by how many cells each day has — a day with 3 cells counts as much as a day with 300.\nA valid day is one where at least 1 cell yields an availability value.\nHow a single cell is computed for this technology: {desc}.\nThreshold {thr}%; below it the card changes colour.',
    'rck.tip.monthAvail': 'Equal-weight mean of {days} valid days = **{avail}%**\nCell-day observations {total} (meeting {meeting} / below {below})\nRoster of {roster} cells = union of every cell of this technology seen this month\nTest: ≥ threshold {thr}%',
    'rck.tip.source': 'Data source: {source}',
    'rck.tip.cellRange': 'This page is **cell-level** availability; the site availability page reads site-level UME values — different calibers, so the two are not directly comparable',
    'rck.tip.cellDrill': 'Click this cell to drill into the cells behind it for that day',
    'rck.tip.cellNoData': '{tech} has no availability value on {day} (not a valid day)',
    'rck.explain.mTotal': 'Cells that **yield an availability value** that day (cell-day observations) = meeting + below; roster cells with no data that day are not here.',
    'rck.explain.mMeeting': 'Cells whose availability ≥ the {thr}% threshold (judged per cell-day, not per site or carrier).',
    'rck.explain.mBelow': 'Cells whose availability < the {thr}% threshold. Meeting + below equals the total row.',
    'rck.explain.mBlank': 'Roster size − cells with a value that day = roster cells with **no data** that day (nothing reported upstream — not availability 0).',
    'rck.explain.mPctMeeting': 'Meeting cells ÷ cells with a value that day — the denominator **excludes** cells with no data, so heavy upstream gaps inflate this share.',
    'rck.explain.mPctBelow': 'Below-threshold cells ÷ cells with a value that day, same denominator as the meeting share.',
    'rck.explain.mAvailability': 'Arithmetic mean of the day\'s cell availabilities (**one vote per cell**), not weighted by traffic, carriers or site importance; red below the {thr}% threshold.',
    'rck.tip.mTotal': '{day}, {tech}: **{total}** of the {roster} roster cells have a value that day ({meeting} meeting + {below} below, {blank} without data)',
    'rck.tip.mMeeting': '{day}: **{v}** cells with availability ≥ the {thr}% threshold ({total} cells had a value that day)',
    'rck.tip.mBelow': '{day}: **{v}** cells with availability < the {thr}% threshold ({total} cells had a value that day)',
    'rck.tip.mBlank': '{day}: roster {roster} − cells with a value {total} = **{v}** cells without data that day (missing report, not availability 0)',
    'rck.tip.mPctMeeting': '{day}: meeting {meeting} ÷ with-value {total} = {v}\nThe denominator **excludes** the {blank} cells without data that day',
    'rck.tip.mPctBelow': '{day}: below {below} ÷ with-value {total} = {v}',
    'rck.tip.mAvailability': '{day}, {tech}: arithmetic mean of {total} cell availabilities = **{v}** (one vote per cell)\nMeeting {meeting} / below {below} / without data {blank}, roster {roster}',
