    'sa.note.filter': 'Filters and time range',
    'sa.note.srcText': 'Site master: db/app.db → master_site_db (site_id, site_name, region, province_county, network_type, fme_name, supervisor, vip_site). Availability is site-level daily: G from remote 2G_Main_Kpi_Site_Daily [TCH in service rate(%)]; U from remote 3G_Main_Kpi_Site_Daily [Cell Validity Rate(%)]; L from remote 4G_Main_Kpi_Site_Daily [[FDD]Cell Availability[SDR_ITBBU]] — all three are native UME site-level values (0~1 ratio). Tdd has no site-level availability field on the remote side, so it is derived from local cell-level Daily_KPI_RPA_CELL_AVAIL_TDD as AVG(Cell Service Time(s))/86400.',
    'sa.note.calcText': 'Daily value = native UME site-level value (for Tdd: mean service time of all TDD cells at that site that day / 86400). Weekly average = arithmetic mean of days in that ISO week (starting Monday) that fall inside the selected month; first/last weeks are trimmed to the month. Monthly average = arithmetic mean of all days with data in the month. Below threshold = days whose value is under the threshold (default 99.65%). Tickets come from eflow_tt, attributed to the month by created_time; status != Closed counts as open. Each ticket is assigned to exactly one site (site_id first, then normalized site name), so counts never double.',
    'sa.note.filterText': 'Time range = the natural calendar month (1st 00:00:00 through last day 23:59:59). Filters: Supervisor, FME (from master_site_db), Technology (which technology the day/week columns expand), and the threshold.',
