    // ---- UME customer KPI: number hover explain (AGENTS.md 3.3c) ----
    'uk.explain.sumKpis': '{{n}} = the number of KPI widgets the API returns; independent of the selected day window.',
    'uk.explain.sumServices': '{{n}} = distinct SERVICE names on the **latest day ({{day}})** only, not every service seen across the window.',
    'uk.explain.sumAttempts': '{{v}} = the attempts of each success-rate card summed, but **every card aggregates the latest day ({{day}}) only** — this is not the selected window total.\nThe backend computes each card with agg(latest_rows); the header just adds those up.',
    'uk.explain.sumFailed': '{{v}} = failures of each card on the latest day ({{day}}), summed.\nFailure definition: when the KPI has reason columns it is system-side + user-side summed; when it has none it is attempts − success (never negative).',
    'uk.explain.sumSysFailed': '{{v}} = **system-side** failure columns summed over the cards\' latest day ({{day}}).\nColouring uses the system-side failure rate = system failures ÷ attempts; user-side failures never affect the colour.',
    'uk.explain.sumUserFailed': '{{v}} = **user-side** failure columns summed over the cards\' latest day ({{day}}).\nIt only feeds the "share of failures that are user-side" ratio and **does not raise an alert** (concentration shows up as an info note).',
    'uk.explain.sumAlerts': '{{n}} = alerts whose level is not info (the API sent {{all}} in total).\nThere are only two thresholds that fire: the system-side failure rate, and the resource daily-average / peak thresholds; a low success rate that stays under them is listed as info.',
    'uk.explain.resAvgTop': 'Daily avg {{avg}} / peak {{top}} = the arithmetic mean and maximum across the {{n}} SERVICE rows of this resource class on the **latest day ({{day}})** — not averaged over the multi-day window.\nColour thresholds: daily avg ≥ {{warn}}% warning, ≥ {{crit}}% critical (overridable by environment variables; always take the values from the API meta.thresholds).',
