    'rsd.warn.malformed': '{n} rows had an occurrence time that does not start with YYYY-MM-DD and were dropped by the backend — **the numbers above exclude them**',
    'rsd.sub.window': 'Window {start} ~ {end}',
    'rsd.sub.rows': 'From {n} outage rows',
    'rsd.sub.ofSites': 'Of {n} site keys',
    'rsd.explain.occurrences': 'One eflow_tt row with site outage = Yes is **one occurrence** (three tickets for the same site on the same day count three times).\nTime column actually used: "{occur}"; outage flag column: "{outage}" — both read from the backend schema probe.\nThe window end is **exclusive at next day 00:00**, so the whole end date is included.',
    'rsd.tip.occurrences': 'Window {start} ~ {end} (the whole {end} is counted)\nRows counted: **{n}**, equal to meta.source_rows from the API\nRows dropped for a malformed time: {malformed}',
    'rsd.explain.sites': 'Sites are counted by **dedupe key**: site ID when present, otherwise the normalised site name (lower-cased, runs of whitespace collapsed to one space).\nRows with neither an ID nor a name collapse into **one** Unknown site, not one per row.',
    'rsd.tip.sites': '**{affected}** site keys after dedupe\nDerived from {events} outage rows (counted per row, not per day)\nDedupe key: site ID first → normalised name → Unknown\n⚠ Different caliber from the alarm dashboard, which dedupes on site_id only',
    'rsd.explain.repeat': 'A repeat-down site is one with **more than one calendar day** holding an outage inside the window.\nIt counts calendar days and **does not require them to be consecutive**: one outage on the 1st and one on the 30th still qualifies.',
    'rsd.tip.repeat': '**{repeat}** repeat-down sites out of {affected} site keys\nTest = the "Down days" column > 1 (backend repeat_days)\nSites down on a single day are not counted',
    'rsd.explain.peak': 'The day with the **highest** daily outage count; on ties the backend takes the **earliest** day of the date-sorted series.\nThe number in the title brackets is that day\'s occurrence count.',
    'rsd.tip.peak': '{day}: **{count}** outages\nAffected sites that day: {sites}\nThe daily series holds {days} days with data',
    'rsd.tip.peakEmpty': 'No outage rows inside window {start} ~ {end}\nThe daily series is empty, so there is no peak day',
    'rsd.explain.chart': 'Bars = outage occurrences that day (one TT row counts once); line = deduped site count; left and right axes are "Occurrences" and "Sites" respectively.\nOnly days **with outages** appear on the x-axis — a quiet day is absent, not drawn as 0.\nTime column: "{occur}".',
    'rsd.explain.rank': 'Sort keys come from the backend _aggregate: occurrences desc, then down days desc, then site name.\nA red tag = down days > 1, i.e. the same set behind the "Repeat-down sites" card above.',
    'rsd.explainCol.occurrences': 'Outage **rows** for this site inside the window: one TT row counts once, several tickets on the same day are counted separately. Time column: "{occur}".',
    'rsd.explainCol.repeatDays': 'Calendar days on which this site had an outage (backend repeat_days), not necessarily consecutive; >1 feeds the "Repeat-down sites" card.',
    'rsd.tip.rowOccurrences': '**{n}** outages for this site in the window\nSpread over {days} calendar days\nSeveral tickets on one day are counted separately',
    'rsd.tip.rowRepeatDays': 'Calendar days with an outage = **{d}**\nTest: more than 1 marks a repeat-down site (red tag)',
    'rsd.tip.drillDay': '{n} outages across {sites} sites\nSame caliber as the cards above: per-row counting, sites by dedupe key',
    'rsd.tip.drillSites': '**{n}** site keys deduped for that day\nRows with neither ID nor name collapse into one Unknown',
    'rsd.tip.drillSite': '{n} outages for this site, spread over {days} calendar days\nThe drill-down matches site ID exactly, and falls back to an exact name match when there is no ID',
    'rsd.tip.drillRepeatDays': 'Calendar days with an outage for this site = **{d}**\nMore than 1 feeds the "Repeat-down sites" card above',
    'rsd.calcNote.title': 'How site outages are counted',
    'rsd.calcNote.secSource': 'Source and flag columns',
    'rsd.calcNote.src1': 'Source table eflow_tt, LEFT JOIN eflow_site for region and site name; the join uses the site ID first and falls back to the **lower-cased, trimmed site name** when the ID side is missing, or joins nothing when neither is available.',
    'rsd.calcNote.src2': 'Outage flag column "{outage}" must be Yes / Y / 1 / true (case and surrounding spaces ignored); occurrence column "{occur}", picked from alarm_occur_time → created_time → last_modified_time as the first one present in the table.',
    'rsd.calcNote.src3': 'Filters: region is an **exact match** on the eflow_site region column, so rows that fail to join a site are excluded; the site box is an **ILIKE substring match** while the drill-down uses exact equality — with a search term hitting several sites the two row counts can differ.',
    'rsd.calcNote.secWindow': 'Time window',
    'rsd.calcNote.window1': 'Current window: {start} ~ {end}.',
    'rsd.calcNote.window2': 'The right bound is **exclusive at next day 00:00**, so the entire end date counts; the default last-30-days window is computed from the **server local clock** (this host runs UTC).',
    'rsd.calcNote.secDedupe': 'Site dedupe',
    'rsd.calcNote.dedupe1': 'Dedupe key = site ID; when the ID is empty, the normalised site name (lower case + whitespace runs collapsed to one space).',
    'rsd.calcNote.dedupe2': 'Rows with neither ID nor name collapse into **one** Unknown site. The alarm dashboard dedupes on site_id only, so the two pages\' site counts are not directly reconcilable.',
    'rsd.calcNote.secRule': 'Counting rule (verbatim from the backend)',
    'rsd.calcNote.rule': '{rule}',
    'rsd.calcNote.ruleMissing': 'The API did not send counting_rule; this page counts one TT row with site_outage=Yes as one outage.',

